// 語言包：de。由 工具/build_langpacks.js 產生，不要直接改（改 工具/translations/ 再重新產生）。
// 經文：Elberfelder 1905 (gemeinfrei)，由 api.getbible.net 取得。
window.LANGPACK = window.LANGPACK || {};
window.LANGPACK.de = {"bible":"Elberfelder 1905 (gemeinfrei)","text":{"421474":"Hier werden deine Antworten unter „Zum Nachdenken“ an jedem Ort gesammelt. Sie werden nur auf diesem Handy gespeichert und nirgendwohin gesendet; nutze vor einem Handywechsel unten „Sicherung exportieren“, dann ist auch dein Tagebuch gesichert.","135xm31":"Das Bergland Gilead","wkt533":"Die mit Eichen und Olivenbäumen bedeckten Hügel im Norden Jordaniens sind das biblische „Gilead“, berühmt für seinen Balsam. Von hier kam der Prophet Elia; hier weinte David um seinen Sohn; und Jesus tat Wunder rund um die Städte der Dekapolis in dieser Gegend.","1d2x3nz":"Frisch gepresstes Olivenöl, Za'atar und Taboon-Brot","1cjupsh":"Das 5. Buch Mose nennt „Olivenbäume“ unter den Gaben des verheißenen Landes. Das Bergland Gilead um Ajloun ist bis heute Jordaniens wichtigstes Olivengebiet. Reiß ein Stück Taboon-Brot ab, tunk es in frisches Olivenöl und dann in Za'atar – das alltäglichste jordanische Frühstück. Von Oktober bis Dezember ist Olivenernte; man kann eine Ölmühle (maʿṣara) besuchen und zusehen, wie das Öl entsteht.","194depr":"Jakobs Heimweg","1mnd10e":"Nach zwanzig Jahren in der Fremde zog Jakob mit seiner ganzen Familie heim – voller Angst vor der Begegnung mit Esau, dem Bruder, den er betrogen hatte. Auf diesem Wegstück östlich des Jordan begegnete er Engeln, rang die ganze Nacht mit Gott und weinte schließlich in den Armen seines Bruders.","x83t5g":"Datteln aus dem Jordantal und Dattelsirup (Dibs)","p2c7g4":"Vom Berg Nebo aus sah Mose „die Ebene des Tales von Jericho, der Palmenstadt“. Das Jordantal ist noch immer voller Dattelpalmen, und seine Medjool-Datteln sind berühmt. Viele Gelehrte meinen, der „Honig“ im „Land, das von Milch und Honig fließt“ sei vor allem eingekochter Dattelsirup gewesen; Jordanier verrühren Dibs mit Tahini und tunken es mit Brot auf. Erntezeit ist August bis Oktober, die frischesten gibt es an den Obstständen am Straßenrand.","1eez5q4":"Die Hauptstadt der Ammoniter","1mrk94d":"Das heutige Amman ist Rabba, die Hauptstadt der Ammoniter in der Bibel. Davids Heer belagerte sie; später hieß sie Philadelphia und wurde eine der Städte der Dekapolis.","cvn3e6":"Saubohnenmus (Fūl)","1k8xpnu":"Als David nach Machanaim floh, war einer der Männer, die ihn versorgten, Schobi „aus Rabba der Kinder Ammon“ – also jemand aus dem heutigen Amman. Die „Bohnen“, die sie brachten, waren Saubohnen; das hebräische pol und das arabische fūl sind dasselbe Wort. Saubohnenmus mit Olivenöl, Zitrone und Kreuzkümmel ist Ammans Lieblingsfrühstück; das alte Restaurant Hashem in der Innenstadt liegt nur ein paar Schritte vom Römischen Theater entfernt.","1k0sh2v":"Am Jordan","bu8bp4":"Hier zog Israel ins verheißene Land; von hier wurde Elia in den Himmel aufgenommen; über tausend Jahre später wurde Jesus hier getauft.","10a38f6":"Wilder Honig","17t30kg":"Johannes der Täufer aß am Jordan „Heuschrecken und wilden Honig“. Honig findet man bis heute leicht: Imker in Ajloun und im Jordantal verkaufen Wildblütenhonig. Heuschrecken sind im Gesetz erlaubt (3. Mose 11,22) und im Islam halal, aber heute essen sie in Jordanien nur noch wenige.","1d5g56e":"Moses letzter Blick","1ln26m6":"Vierzig Jahre in der Wüste gehen zu Ende. Vom Berg Nebo blickt Mose über das Land, nach dem er sich sehnte und das er doch nicht betreten sollte.","48jt25":"Fladenbrot mit Za'atar (Manaqish)","1mb20zw":"In der Nacht, als Mose Israel aus Ägypten führte, strichen sie mit „Ysop“ das Blut des Lammes an die Türpfosten. Viele Gelehrte halten diese Pflanze (hebräisch ezov) für den wilden Za'atar des Nahen Ostens. Heute verkaufen die Bäckereien in Madaba heißes Fladenbrot mit Za'atar und Olivenöl – ein Geschmack vom Passah-Kraut, dort wo Mose ins verheißene Land blickte.","1wgtped":"Johannes der Täufer und der König von Moab","101xyls":"Südlich vom Berg Nebo liegt das alte Moab. Hier wurde Johannes der Täufer in einer Bergfestung enthauptet, und König Mesa von Moab ließ einen Stein beschriften, der dreitausend Jahre später ausgegraben wurde und den Bericht aus den Königsbüchern widerspiegelt.","1cxtob4":"Trauben und Traubensirup (Dibs ʿInab)","cs10iv":"Jesaja nennt in seiner Klage über Moab die Weinberge und Keltern von Hesbon, Elale und Sibma. Hier wird noch immer Wein angebaut. Zur Zeit der Bibel wurden die meisten Trauben zu Wein (alkoholisch, nicht halal); um „die Trauben Moabs“ zu kosten, iss im August und September frische Trauben oder gefüllte Weinblätter, oder kauf den Traubensirup, den Jordanier zu Hause einkochen.","1glv2pg":"Ruths Heimat","80l5ap":"Jenseits der Arnon-Schlucht liegt das Herz Moabs: die Hochebene um Kerak. Von hier folgte Ruth ihrer Schwiegermutter nach Bethlehem und wurde die Urgroßmutter von König David. Unten im Westen, am Südende des Toten Meeres, floh Lot aus Sodom – dort begann die Geschichte der Moabiter.","1p53r6w":"Mansaf und Freekeh aus Kerak","iisgvz":"Mesa, der König von Moab, „war ein Herdenbesitzer“. Kerak ist bis heute für seine Herden bekannt, und das Nationalgericht Mansaf ist Lammfleisch in einer Soße aus Jameed (getrockneten Joghurtkugeln) – der Jameed aus Kerak ist der berühmteste. Ruth aß „geröstete Körner“, ganz ähnlich wie das heutige Freekeh: grüner Weizen, im Frühling über dem Feuer geröstet und dann gedroschen. (Wer kein Lamm isst, bestellt die Hühnchen-Variante, Mansaf Djāj.)","1ricw2j":"Das Land Edom","vapb23":"Jenseits des Baches Sered liegt das Land der Nachkommen Esaus, der Edomiter. Edom heißt „rot“, und die Berge hier sind wirklich rot. Hier endeten Israels achtunddreißig Jahre Wüstenwanderung, und an diesem Weg blickten sie auf zur ehernen Schlange, die Mose aufgerichtet hatte.","hpzlhu":"Linsensuppe (Schōrbit ʿAdas)","1nk7trk":"Esau verkaufte sein Erstgeburtsrecht für eine Schüssel rotes Gericht – darum wurde er Edom genannt. Das Gericht waren Linsen: das hebräische ʿadashim und das arabische ʿadas sind dasselbe Wort. Linsensuppe steht im Winter auf fast jeder jordanischen Speisekarte, mit einem Spritzer Zitrone und einer Prise Kreuzkümmel. Eine Schüssel in Esaus Heimat zu essen, ist das Beste daran.","xqwzi5":"Das Tor zum Roten Meer","azugso":"Die letzte Etappe der Reise führt von Petra, der Stadt aus rotem Sandstein, nach Süden bis Aqaba am Roten Meer. Hier herrschte Aretas, der König der Nabatäer, und Paulus ging nach seiner Bekehrung nach Arabien; Aaron starb auf einem Berg in dieser Gegend, und Salomos Schiffe stachen von dieser Küste aus in See. Wenn du das Meer erreichst, bist du durch das ganze Land jenseits des Jordan gewandert.","18ivhio":"Beduinenbrot aus der Asche (Arbood) und Beduinentee","1bjqj9z":"Als Elia zu erschöpft war, um weiterzugehen, stellte ihm ein Engel „einen auf glühenden Steinen gebackenen Kuchen“ und einen Krug Wasser neben den Kopf. Die Beduinen rund um Petra vergraben den Teig noch heute in heißer Asche, um Arbood zu backen, oder backen dünnes Shrak-Brot auf einer umgedrehten Eisenkuppel, dazu süßen Kräutertee. Ihre Art, jeden Gast willkommen zu heißen, kommt der biblischen Gastfreundschaft heute wohl am nächsten.","1k05vmw":"Gnade und Berufung (nördliches Jordantal)","1o29u94":"Zwischen dem Bergland Gilead (Kapitel 1) und dem Jabbok (Kapitel 2) liegt ein wenig besuchter Abschnitt des Jordantals. Hier verließ Elisa seinen Pflug, um Elia zu folgen; Barsillai und Makir versorgten David auf der Flucht; und die frühe Gemeinde fand Zuflucht. Er lässt sich leicht mit Kapitel 1 und 2 in einer Reise verbinden.","1ige4b4":"Bestell von Barsillais Vorratsliste","15vld6g":"Barsillai, Makir und Schobi brachten David Weizen, Gerste, geröstete Körner, Bohnen, Linsen, geröstete Kichererbsen, Honig, Butter und Käse. All das kann man heute in Jordanien bestellen: Fūl, Linsensuppe, geröstete Kichererbsen, Honig, Samneh (geklärte Butter) und weißen Käse. Such dir ein einfaches, hausgemachtes Lokal und bestell einen Tisch voll von dieser Liste zum Teilen.","1p7om67":"Entscheidungen östlich des Jordan (im ganzen Land)","xiwsvo":"Die Orte dieser Nebenroute sind über ganz Jordanien verstreut und von der Hauptroute aus gut zu erreichen. Sie haben eines gemeinsam: Hier traf jemand eine Entscheidung. Israel entschied sich, außen herum zu ziehen, statt sich den Weg zu erzwingen; Ruben und Gad entschieden sich, an der Seite ihrer Brüder zu kämpfen; Gott entschied sich, denen einen Ausweg zu schaffen, die versagt hatten; und Hiob, der alles verloren hatte, entschied sich, anzubeten.","156xc2t":"Frischer Joghurt (Laban) und Labneh","1o6b8tn":"Ruben und Gad wählten Jaser und Gilead, weil es „ein Ort für Vieh“ war. Jordaniens Hirten weiden ihre Herden noch immer an diesen Hängen, und Joghurt (Laban) und abgetropfter Joghurt (Labneh) gehören zum Alltag. Zum Frühstück bestellst du einen Teller Labneh mit Olivenöl, dazu Brot und Gurken.","cyxc6a":"Wasser und Segen","jqt7xr":"So viele Geschichten dieses Landes haben mit Wasser zu tun: Der Jordan blieb stehen, damit Israel hinüberziehen konnte, in der Wüste sprudelte ein Brunnen, das Tote Meer wurde in der Vision eines Propheten lebendig, und ein ausländischer Feldherr wurde im Jordan rein. Und da ist Bileam, angeheuert zum Fluchen, der nur Segen aussprechen konnte.","1kcdwta":"Tilapia aus dem Jordantal (Musht)","clzxt8":"Hesekiel sah: Wenn das lebendige Wasser das Salzmeer erreicht, „werden Fischer an ihm stehen … nach ihrer Art werden seine Fische sein“. Das Tote Meer hat bis heute keine Fische, aber im Jordantal wird Tilapia gezüchtet, hier Musht oder „Petrusfisch“ genannt. Iss in einem Restaurant im Tal oder in Irbid einen gegrillten Fisch und denk an Hesekiels Vision.","qbfsvh":"Gadara (Umm Qais)","o70mou":"Ausgrabungsstätte Umm Qais mit Blick auf den See Genezareth","1d9otqb":"Jesus fuhr über den See Genezareth in „das Land der Gadarener“ (manche Handschriften und Übersetzungen, darunter die World English Bible, lesen „Gergesener“) und traf zwei Besessene, die in den Grüften hausten – so gefährlich, dass niemand diesen Weg zu gehen wagte. Jesus trieb die Dämonen aus; sie baten, in eine große Herde Schweine fahren zu dürfen, und die Herde stürzte den Abhang hinab in den See und ertrank. Gadara war eine der Städte der Dekapolis – das heutige Umm Qais. Die Stadt selbst liegt etwa 10 km vom See entfernt, das Wunder geschah also wohl auf Gadaras Land am Ufer. Neben dem Theater aus schwarzem Basalt überblickt man den ganzen See Genezareth und die Golanhöhen – genau die Gegend, in der Jesus den größten Teil seines Wirkens verbrachte.","1nniquf":"Nachdem die beiden Männer geheilt waren, baten die Leute Jesus, wegzugehen – sie hatten ihre Schweine verloren. Gibt es einen „Verlust“, der dich zögern lässt, Gott in deinem Leben wirken zu lassen?","1hvgznf":"🌊 Aufgabe: Geh zum Aussichtspunkt im Westen und mach ein Foto mit dem See Genezareth. Die meisten Wunder Jesu geschahen rund um den See vor dir.","norv2w":"In welche Tiere fuhren die Dämonen, als Jesus sie austrieb?","1pza0ap":"Eine Schafherde","mrurcj":"Eine Schweineherde","1ezomfp":"Eine Rinderherde","1d5z0am":"Im äußersten Nordwesten Jordaniens, etwa 2 Stunden Fahrt von Amman oder 30 Minuten von Irbid. Eintritt kostenpflichtig (Jordan Pass gilt). Ein Restaurant vor Ort bietet Seeblick zum Essen. Nahe der Grenze – Reisepass mitnehmen.","xwz24m":"Gerasa (Jerash)","v16rmo":"Die antike Stadt Jerash, eine römische Stadt der Dekapolis","16b1gez":"Markus und Lukas nennen den Ort des Schweine-Wunders „das Land der Gerasener“. Gerasa ist das heutige Jerash, liegt aber über fünfzig Kilometer vom See Genezareth entfernt; gemeint ist also wohl das weite Gebiet, das diese große Stadt beherrschte; die Evangelien schreiben den Namen außerdem unterschiedlich. Der Geheilte wollte Jesus folgen, doch Jesus sagte ihm, er solle nach Hause gehen und den Seinen erzählen, was der Herr an ihm getan hatte. Er verkündete es in der ganzen Dekapolis, und alle wunderten sich. Jerash ist eine der am besten erhaltenen römischen Städte der Welt, mit dem Hadriansbogen, dem Ovalen Platz, einer Säulenstraße und über einem Dutzend byzantinischer Kirchen mit wunderschönen Mosaikböden.","1qy5z4e":"Jesus ließ den Mann nicht mitgehen; er schickte ihn „nach Hause“, um seine Geschichte zu erzählen. Kann es sein, dass gerade deine eigene Familie und deine Nachbarn deine Geschichte am meisten hören müssen?","kvtwue":"⛪ Aufgabe: Such einen Mosaikboden einer byzantinischen Kirche (zum Beispiel in der Kirche der Heiligen Kosmas und Damian) und schau, welche Tiere darauf zu sehen sind. Gläubige haben sie vor über 1.400 Jahren hinterlassen.","10ew1d7":"Wo verkündete der Geheilte, was Jesus an ihm getan hatte?","32vcwl":"Jerusalem","1jxb2o2":"In der Dekapolis","1nwdpmw":"Ägypten","jo8c47":"Etwa 50 km nördlich von Amman, rund eine Stunde Fahrt; Busse fahren auch vom Nord-Busbahnhof Amman (Tabarbour). Eintritt kostenpflichtig. Das Gelände ist riesig – plane mindestens einen halben Tag ein und nimm Wasser, Hut und bequeme Schuhe mit.","1pgtur5":"Tisbe: Elias Heimatort (Mar Elias)","1n4tj7t":"Kirchenruine auf einem Hügel beim Dorf Listib, nahe Ajloun","suhywi":"In 1. Könige 17 tritt Elia mit einer einzigen Zeile Vorstellung auf die Bühne der Geschichte: „Elia, der Tisbiter, aus den Beisassen Gileads“. Er sagte König Ahab, es werde weder Tau noch Regen geben, außer auf sein Wort. Jakobus erinnert uns: „Elia war ein Mensch von gleichen Gemütsbewegungen wie wir.“ Wo Tisbe lag, ist unter Gelehrten bis heute umstritten; die Tradition verortet es beim Dorf Listib nahe Ajloun, wo auf einem Hügel die Ruinen einer byzantinischen Kirche namens Mar Elias (Heiliger Elia) liegen, eine der christlichen Pilgerstätten Jordaniens. Die Hügel ringsum mit Eichen und Oliven sind das biblische „Gilead“, berühmt für seinen Balsam.","1bywsn":"Elia war ein gewöhnlicher Mann aus den ländlichen Bergen, und doch wagte er, einem König die Wahrheit zu sagen. Gibt es etwas in deinem Umfeld, das braucht, dass du mutig die Wahrheit sagst?","1i2fzuq":"🌳 Aufgabe: Such auf dem Gipfel nach Resten des Mosaikbodens der Kirche, und schau dann auf die Hügel ringsum – wie viele Baumarten erkennst du?","1vqnpnh":"Was würde nach Elias Worten an König Ahab nicht fallen?","drrkld":"Feuer und Schwefel","1xdg1k8":"Tau und Regen","1o60iae":"Manna","10scmat":"Auf einem Hügel beim Dorf Listib nahe Ajloun, etwa anderthalb Stunden Fahrt von Amman; folge den Schildern „Mar Elias“. Kleines Gelände mit Parkplatz. Gut mit der Burg Ajloun zu verbinden. Oben ist es windig und im Winter kalt. (Ungefähre Lage, deshalb ist der Check-in-Radius groß.)","1ijwqya":"Beth-Arbeel (Irbid)","11y0d81":"Tell Irbid, der antike Siedlungshügel im Zentrum von Irbid","evvr4":"Als der Prophet Hosea Israel warnte, erinnerte er an eine Katastrophe, die jeder kannte: „wie Salman Beth-Arbeel zerstörte am Tage des Krieges“, als sogar Mütter samt ihren Kindern zerschmettert wurden. Viele Gelehrte setzen Beth-Arbeel mit Tell Irbid gleich, dem antiken Hügel im Zentrum von Irbid – der Name hat sich kaum verändert. Heute ist Irbid eine große Universitätsstadt im Norden Jordaniens, und ein altes Steingebäude aus osmanischer Zeit auf dem Hügel ist ein Museum geworden.","y9x5ss":"Hosea nutzte ein schmerzhaftes Stück Geschichte, um das Volk daran zu erinnern, dass Vertrauen auf die eigene Stärke es im Stich lassen würde. Worauf verlässt du dich gerade am meisten?","bphd0v":"🏛️ Aufgabe: Steig auf den Hügel in der Innenstadt und such das alte Steinhaus (Museum Dar As-Saraya). Unter deinen Füßen liegen Städte, Schicht um Schicht, über Tausende von Jahren.","1bqwilo":"Welcher Prophet erwähnt Beth-Arbeel?","1gk8i8n":"Hosea","undsd5":"Jona","ob4vl2":"Haggai","1i1meg4":"In der Innenstadt von Irbid, etwa 1 Stunde 15 Minuten Fahrt von Amman; Busse fahren auch vom Nord-Busbahnhof Amman. Öffnungszeiten des Museums vor Ort erfragen.","lpqkjx":"Ramot-Gilead","z2jbfn":"Tell er-Rumeith bei Ramtha","3ummau":"Ramot-Gilead war eine wichtige Stadt östlich des Jordan und eine der drei „Zufluchtsstädte“, in die jemand fliehen konnte, der versehentlich einen Menschen getötet hatte. König Ahab missachtete die Warnung des Propheten Micha und zog als einfacher Soldat verkleidet in die Schlacht – doch „ein Mann spannte den Bogen aufs Geratewohl“, der Pfeil traf ihn zwischen die Fugen des Panzers, und Ahab starb. Später sandte der Prophet Elisa einen jungen Mann hierher, um Jehu zum König über Israel zu salben. Viele Gelehrte setzen den Ort mit Tell er-Rumeith bei Ramtha gleich, direkt an der syrischen Grenze – eine Grenzfestung seit alters her.","1ge8yir":"Ahab meinte, eine Verkleidung könne Gottes Wort ausweichen, doch ein Pfeil „aufs Geratewohl“ fand ihn. Gibt es etwas, dem du meinst ausweichen zu können, dem du dich aber eigentlich direkt stellen musst?","otjz2z":"🛡️ Aufgabe: Stell dich auf den Hügel und stell dir eine antike Zufluchtsstadt vor: Für jemanden, der nirgends hinfliehen konnte, bedeutete der Anblick dieser Stadt Hoffnung. (Bitte halte Abstand zu Grenzkontrollzonen.)","1qgrb2q":"Was tat König Ahab, als er in die Schlacht zog?","v78w4i":"Er trug seine königlichen Gewänder","1iezfse":"Er verkleidete sich","2xgcmu":"Er blieb in der Stadt","1isfmcp":"⚠️ Ein archäologischer Siedlungshügel ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt. Er liegt bei Ramtha an der syrischen Grenze: Reisepass mitnehmen, Anweisungen von Polizei und Militär befolgen und Grenzkontrollzonen meiden.","1jsz48b":"Jabes-Gilead","16fd6eu":"Tell el-Maqlub im Tal Wadi al-Yabis","1p9spy9":"Nahas, der König der Ammoniter, belagerte Jabes-Gilead und stellte Bedingungen für die Kapitulation: Er wollte jedem Bewohner das rechte Auge ausstechen. Als Saul davon hörte, kam der Geist Gottes über ihn, und er marschierte die ganze Nacht, um die Stadt zu retten – sein erster Sieg als König. Jahre später fiel Saul auf dem Berg Gilboa, und die Philister hängten seinen Leichnam an die Mauer von Beth-Schean. Die tapferen Männer von Jabes vergaßen seine Güte nie: Sie gingen die ganze Nacht, holten die Leichname Sauls und seiner Söhne, begruben sie und fasteten sieben Tage. Heute heißt das Tal Wadi al-Yabis und trägt noch immer den Namen „Jabes“; viele Gelehrte setzen die Stadt mit Tell el-Maqlub im Tal gleich.","2zcakl":"Jahrzehnte später erinnerten sich die Leute von Jabes noch an Sauls Güte und riskierten ihr Leben, um sie zu vergelten. Gibt es jemanden, der dir einmal geholfen hat und dem du danken könntest?","1ld3nc6":"🙏 Aufgabe: Denk an jemanden, der dir einmal geholfen hat, und schick ihm heute eine Dankesnachricht.","nyfyg5":"Was taten die tapferen Männer von Jabes nach Sauls Tod?","xci98a":"Sie ergaben sich den Philistern","8ze3b2":"Sie holten Sauls Leichnam über Nacht und begruben ihn","1p7o4e3":"Sie flohen nach Ammon","1pl2pkt":"⚠️ Ein archäologischer Hügel im Tal Wadi al-Yabis ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt. Er liegt auf dem Weg von Ajloun hinunter ins Jordantal. Einchecken kannst du überall in der Nähe.","1d2hf6r":"Der Bach Krith (Raben versorgen Elia)","l6s93b":"Lage unsicher: vorgeschlagen werden Wadi al-Yabis oder Wadi Kharrar bei der Taufstelle","fqivg8":"Nachdem Elia Ahab gesagt hatte, es werde nicht regnen, schickte Gott ihn, sich am Bach Krith östlich des Jordan zu verbergen. Er trank aus dem Bach, und Raben brachten ihm morgens und abends Brot und Fleisch. Nach einiger Zeit vertrocknete der Bach, weil es nicht regnete, und Gott führte ihn an den nächsten Ort. Die genaue Lage des Krith ist unsicher – vorgeschlagen werden Wadi al-Yabis und Wadi Kharrar bei der Taufstelle –, deshalb ist dies ein verborgenes Level.","1c0gp10":"Erst als der Bach vertrocknete, zog Elia weiter. Ist dir schon einmal ein „Bach“, auf den du dich verlassen hast, vertrocknet – und später hast du gemerkt, dass Gott dich weiterführte?","1geo4kb":"🔒 Verborgene Aufgabe: Lies 1. Könige 17, um zu sehen, wohin Gott Elia schickte, als der Bach vertrocknet war, und komm dann zum Quiz zurück.","saljle":"Wer brachte Elia am Bach Krith zu essen?","h5kuq7":"Ein Engel","c2ygju":"Raben","avuy2":"Eine Witwe","c04xc6":"Dies ist ein verborgenes Level: Die genaue Lage ist unbekannt, du musst also nicht hinfahren. Beantworte das Quiz richtig, um den Stempel freizuschalten.","1pw93o6":"Der Wald Ephraim (Absaloms Tod)","v53tut":"Lage unsicher, im Bergland Gilead östlich des Jordan","1jw6ysh":"Trotz seines Namens lag dieser Wald in Gilead, östlich des Jordan. Als Davids Sohn Absalom sich auflehnte, kämpften die beiden Heere im Wald Ephraim, und „der Wald fraß mehr unter dem Volke, als das Schwert fraß“. Als Absalom auf seinem Maultier unter den dichten Zweigen einer großen Terebinthe hindurchritt, blieb er mit dem Kopf hängen und schwebte zwischen Himmel und Erde, und Joab tötete ihn. Als die Nachricht David erreichte, weinte er im Gehen: „Mein Sohn Absalom! Mein Sohn, mein Sohn Absalom! Wäre ich doch an deiner Statt gestorben!“ Die genaue Lage ist unbekannt, deshalb ist dies ein verborgenes Level.","17mo35x":"Absalom verriet David, und doch brach Davids Herz um ihn – so ist das Herz von Eltern oft. Was könntest du heute für deine Eltern oder deine Familie tun?","74y5n5":"🔒 Verborgene Aufgabe: Lies 2. Samuel 18 und komm dann zum Quiz zurück.","1b30ln6":"Was hielt Absalom fest, als er auf seinem Maultier vorbeiritt?","1ajscp3":"Ein Weinstock","5a4w6b":"Die dichten Zweige einer großen Terebinthe","14e5y5y":"Ein Stadttor","1vmqy52":"Der Jabbok (heute der Fluss Zarqa)","1arrgay":"Jabbok-Tal: König-Talal-Damm und Gegend von Tulul adh-Dhahab","1rz7fy3":"Jakob hatte zwanzig Jahre bei seinem Onkel Laban gelebt. Nun zog er mit seinen Frauen, Kindern und Herden heim – und hörte, dass sein Bruder Esau mit vierhundert Mann kam; er fürchtete sich sehr. In jener Nacht ließ er seine Familie die Furt des Jabbok überqueren und blieb allein zurück. Ein Mann rang mit ihm, bis die Morgenröte aufging; durch eine Berührung wurde Jakobs Hüfte verrenkt, und doch sagte er: „Ich lasse dich nicht, du habest mich denn gesegnet.“ Der Mann gab ihm den neuen Namen „Israel“. Interessant: Im Hebräischen klingt „Jabbok“ wie das Wort für „ringen“. Am nächsten Tag lief Esau ihm entgegen und umarmte ihn, und die beiden Brüder weinten. Heute heißt der Fluss Zarqa („blau“), der zweitgrößte Nebenfluss des Jordan.","1dfb697":"Bevor Jakob sich mit seinem Bruder versöhnte, rang er die ganze Nacht mit Gott. Gibt es eine Beziehung, die du heilen musst? Was musst du zuerst zu Gott bringen, bevor du diesem Menschen begegnest?","x9544a":"🌄 Aufgabe: Such dir einen Platz oberhalb des Tals und sei fünf Minuten allein und still – auch Jakob war in jener Nacht allein. Wenn es früh am Morgen ist, schau, über welchen Hügeln die Sonne aufgeht.","rrc68y":"Welchen neuen Namen bekam Jakob nach dem Ringen am Jabbok?","1srzgkf":"Abraham","zz5fut":"Israel","1ivdut8":"Edom","1jcuvn7":"Das Jabbok-Tal ist lang, deshalb hat diese Station zwei Check-in-Bereiche – beide zählen: ① der König-Talal-Damm, ein kleiner Abstecher auf der Straße von Amman nach Jerash; ② die Gegend von Tulul adh-Dhahab, wo sich das Tal östlich von Deir Alla zum Jordantal öffnet. (Ungefähre Lage, deshalb ist der Check-in-Radius groß.)","16dwmmh":"Sukkoth (wo Jakob Hütten baute)","hk7a1g":"Siedlungshügel Tell Deir Alla im Jordantal","115c6us":"Nachdem er sich mit Esau versöhnt hatte, kam Jakob nach Sukkoth, baute sich ein Haus und machte Hütten für sein Vieh – darum nannte man den Ort „Sukkoth“, das heißt „Hütten“ oder „Laubhütten“. Das jüdische Laubhüttenfest verwendet dasselbe Wort. Jahrhunderte später ließ König Salomo die Bronze für den Tempel in der Tonebene „zwischen Sukkoth und Zarethan“ gießen. 1967 fanden niederländische Archäologen bei Ausgrabungen auf diesem Hügel einen alten Text auf Putz, der „Bileam, Sohn Beors“ nennt – genau den Propheten aus dem 4. Buch Mose. Es war das erste Mal, dass Bileams Name außerhalb der Bibel gefunden wurde.","r6ii6z":"Nach jener Nacht des Ringens und jener Versöhnung ließ sich Jakob endlich in Sukkoth nieder. Wo ist die „Hütte“ in deinem Leben, an der du anhalten und wirklich ausruhen kannst?","v9hzr6":"🏺 Aufgabe: Stell dich auf den Hügel und schau über die Felder ringsum. In dieser Tonebene goss Salomo die Bronzen für den Tempel. Geh in die Hocke und fühl die Erde.","wbq0tj":"Was bedeutet „Sukkoth“?","kzm99p":"Quellen","di0aqv":"Hütten / Laubhütten","1r0wx3k":"Hoher Berg","16jhazd":"Beim Ort Deir Alla im Jordantal, etwa eine Stunde Fahrt von Amman über Salt. Der Hügel liegt direkt an der Straße; er ist klein und hat kaum Einrichtungen. Im Sommer ist das Tal sehr heiß – fahr am Vormittag hin.","mpsyfs":"Pnuel (das Angesicht Gottes)","r105rm":"Der östliche Hügel von Tulul adh-Dhahab („Goldhügel“)","mtzx5w":"Nach dem Ringen nannte Jakob diesen Ort Pniel, „Angesicht Gottes“, und sagte: „Ich habe Gott von Angesicht zu Angesicht gesehen, und meine Seele ist gerettet worden.“ Die Sonne ging auf, als er hinkend vorüberzog. Jahrhunderte später, als der Richter Gideon die Feinde verfolgte, baten seine erschöpften, hungrigen Soldaten die Leute von Pnuel um Brot – und wurden abgewiesen; danach riss Gideon ihren Turm nieder. Hier macht der Jabbok eine große Biegung zwischen zwei Hügeln namens Tulul adh-Dhahab, arabisch für „Goldhügel“. Viele Gelehrte setzen den östlichen Hügel mit Pnuel gleich.","1ku3hb2":"Jakob hinkte in den Sonnenaufgang. Gibt es in deinem Leben eine Wunde, die später zum Zeichen deiner Begegnung mit Gott wurde?","phri4k":"🌅 Aufgabe: Schau aus der Ferne auf die Flussbiegung zwischen den beiden Hügeln und stell dir vor, wie Jakobs Familie in der Nacht durchs Wasser watet.","1ufietx":"Was bedeutet „Pnuel“?","3u39cg":"Das Angesicht Gottes","h49w0f":"Das Haus Gottes","g0lrby":"Der Berg Gottes","1xtxpbw":"⚠️ Ein archäologischer Hügel im Flusstal ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt, die Hänge sind steil. Er liegt im Jabbok-Tal östlich von Deir Alla. Geh mit jemandem, der sich auskennt, und meide den Ort bei starkem Regen oder Hochwasser.","1k5pu8c":"Machanaim (zwei Lager)","im8jpq":"Der westliche Hügel von Tulul adh-Dhahab","1iaoamq":"Auf dem Heimweg begegnete Jakob den Engeln Gottes und sagte: „Dies ist das Heerlager Gottes“, und nannte den Ort Machanaim, „zwei Lager“. Später wurde Machanaim eine wichtige Stadt: Sauls Sohn Isboseth regierte hier, und als David vor seinem Sohn Absalom floh – an seinem Tiefpunkt –, kam auch er hierher. Barsillai, der Gileaditer, und einige Freunde brachten Betten, Schalen, Weizen, Bohnen, Honig und Butter und sagten: „Das Volk ist hungrig und matt und durstig in der Wüste.“ Viele Gelehrte setzen den westlichen Hügel von Tulul adh-Dhahab mit Machanaim gleich, es gibt aber auch andere Vorschläge.","ee2j09":"An Davids Tiefpunkt kamen Freunde mit Betten und Essen. Ist jemand in deinem Umfeld gerade in der „Wüste“? Was könntest du ihm bringen?","cxzmz2":"🍯 Aufgabe: Bring wie Barsillai etwas zu essen mit und teile es mit deinen Begleitern oder mit jemandem, den du hier triffst.","150pg5e":"Was bedeutet „Machanaim“?","fadiws":"Quellkopf","sa7ilb":"Zwei Lager","1nbs9zq":"Weinberge","2sk8x7":"⚠️ Der Zwilling von Pnuel, auf der Westseite der Flussbiegung; ebenfalls ohne Besuchereinrichtungen, Zugang nicht bestätigt. Geh mit jemandem, der sich auskennt.","1jbfbfw":"Mizpa in Gilead (der Bund zwischen Jakob und Laban)","1ys2y8e":"Lage unsicher; manche vermuten den Berg Jal'ad nördlich von Salt","10k3aad":"Jakob stahl sich mit seiner ganzen Familie von seinem Onkel Laban davon; Laban jagte ihm sieben Tage nach und holte ihn im Gebirge Gilead ein. Nach einem Streit schlossen sie einen Bund und schichteten Steine als Zeugen auf. Laban nannte den Haufen auf Aramäisch Jegar-Sahadutha, Jakob nannte ihn auf Hebräisch Galed – beides heißt „Zeugenhaufen“. Er hieß auch Mizpa, „Warte“, denn Laban sagte: „Jehova sei Wächter zwischen mir und dir, wenn wir einer vor dem anderen verborgen sein werden.“ Heute wird dieser Satz oft als Segen in Halsketten für Paare graviert, ursprünglich war er aber eine Grenze zwischen zwei Männern, die einander nicht trauten: Keiner sollte den Haufen überschreiten, um dem anderen zu schaden. Die genaue Lage ist unbekannt, deshalb ist dies ein verborgenes Level.","qy46k":"Mizpa war ursprünglich eine Grenze, die zwei Menschen ein friedliches Leben ermöglichte. Gibt es in deinen Beziehungen einen Punkt, an dem du klar reden und eine gesunde Grenze setzen musst?","4zcgts":"🔒 Verborgene Aufgabe: Lies 1. Mose 31, um herauszufinden, worüber Jakob und Laban stritten, und komm dann zum Quiz zurück.","d6uo0v":"Welchen hebräischen Namen gab Jakob dem Steinhaufen?","xna3az":"Galed","op2pxx":"Bethel","1rhr63l":"Gilgal","tzrg5k":"Rabba: die Zitadelle von Amman","kot5tx":"Jabal al-Qal'a (Zitadellenhügel), Innenstadt von Amman","l0ym10":"Die Ammoniter waren Nachkommen Lots, und ihre Hauptstadt Rabba stand auf diesem Hügel. Das 5. Buch Mose sagt, dass das riesige eiserne Bett von Og, dem König von Basan – neun Ellen lang –, in Rabba aufbewahrt wurde. Später schickte David Joab, um Rabba zu belagern, während er selbst in Jerusalem blieb und dort mit Bathseba sündigte. Um es zu vertuschen, schrieb er Joab, ihren Mann Urija „voran, wo der Streit am stärksten ist“ zu stellen, und Urija starb unter diesen Mauern. Jahrhunderte später kündigte der Prophet Amos Feuer an, das die Paläste von Rabba verzehren würde. Heute stehen auf dem Hügel ein römischer Herkulestempel, eine byzantinische Kirche und ein umayyadischer Palast – über dreitausend Jahre Geschichte in Schichten.","ijk6l6":"Davids Fall begann, als er „zur Zeit, wann die Könige ausziehen“, zu Hause blieb. Gibt es einen Bereich in deinem Leben, in dem du wachsam sein solltest, aber deine Deckung vernachlässigt hast?","p0kw67":"✋ Aufgabe: Such die riesige Steinhand neben dem Herkulestempel und mach ein Foto mit deiner Hand daneben (nur Foto – nicht hinaufklettern). Geh dann zur Mauer und schau hinunter, wo das Römische Theater liegt.","irai9v":"Wen schickte David, um Rabba zu belagern?","1sew60r":"Abner","l2h7ud":"Joab","i0hfsr":"Nathan","nb300p":"Auf einem Hügel in der Innenstadt von Amman; sag deinem Taxi, Careem oder Uber „Al-Qal'a“ (die Zitadelle). Eintritt kostenpflichtig. Ein kleines archäologisches Museum auf dem Hügel zeigt Funde aus vielen Epochen, auch aus der ammonitischen Zeit. Der Sonnenuntergang über der Stadt ist wunderschön, aber es gibt wenig Schatten – tagsüber Wasser mitnehmen.","f5wsnh":"Philadelphia: das Römische Theater","8uxvfv":"Innenstadt von Amman, unterhalb des Zitadellenhügels","1im1jk5":"Im 3. Jahrhundert v. Chr. benannte Ptolemaios II. von Ägypten Rabba in „Philadelphia“ um („Bruderliebe“). In römischer Zeit gehörte die Stadt zur Dekapolis, den „Zehn Städten“. Dieses Theater wurde im 2. Jahrhundert n. Chr. gebaut, fasst etwa sechstausend Menschen und wird bis heute genutzt. Die Evangelien berichten, dass große Mengen „aus der Dekapolis“ Jesus folgten, und Jesus selbst zog durch das Gebiet der Dekapolis. Die Bibel sagt nicht, dass Jesus nach Philadelphia kam, aber Leute aus dieser Stadt, die ihn hören gingen, könnten auf genau diesen Stufen gesessen haben.","11zd6o":"Der Name dieser Stadt bedeutet „Bruderliebe“. Wie könntest du diesen Namen in der Stadt, in der du lebst, ausleben?","1758p37":"🗣️ Aufgabe: Stell dich auf die Mitte der Bühne und sprich leise, während ein Begleiter oben auf den Rängen zuhört. Die Römer hatten keine Mikrofone, und doch ist die Akustik verblüffend!","1uxwbh6":"Wie wurde Rabba in griechischer und römischer Zeit genannt?","eykezm":"Philadelphia","280ec4":"Cäsarea","k02nqt":"Antiochia","1gpvfvy":"Am Fuß des Zitadellenhügels – etwa 15–20 Minuten zu Fuß bergab von der Zitadelle, oder mit dem Auto zum „Roman Theatre / Al-Mudarraj al-Roumani“. Eintritt kostenpflichtig; zwei kleine Volkskundemuseen liegen neben dem Theater. Der Haschemitische Platz nebenan ist ein schöner Ort zum Ausruhen.","19v40sn":"Rabbas „Wasserstadt“: Ras al-Ain","1kzc4rs":"Ras al-Ain („Quellkopf“), südwestlich der Innenstadt von Amman","k0encj":"Bei der Belagerung Rabbas nahm Joab zuerst die „Wasserstadt“ ein und ließ David sagen: Komm schnell, die Stadt steht kurz vor dem Fall. Antike Städte fürchteten nichts so sehr wie den Verlust ihres Wassers; wer die Quelle hatte, hatte die halbe Schlacht gewonnen. Einst floss ein Bach durch Ammans Tal, von den Quellen bei Ras al-Ain („Quellkopf“) durch die Innenstadt. Viele Gelehrte meinen, die von Joab eingenommene „Wasserstadt“ sei die Unterstadt gewesen, die diese Wasserversorgung schützte. Der Bach floss bis ins 20. Jahrhundert; heute hat die Stadt ihn überbaut, nur der Name ist geblieben.","280bj8":"Die Stärke einer Stadt lag in ihrer verborgenen Quelle. Woher kommt deine Kraft?","m84rf0":"💧 Aufgabe: Such auf Straßenschildern oder Ladennamen in der Nähe nach „Ain“ oder „عين“ (Quelle). Viele Ortsnamen in Amman haben mit Wasser zu tun!","832nby":"Was bedeutet „Ras al-Ain“?","1xtxgno":"Der Hügel des Königs","1cc7u0c":"Das große Tor","1ulqaaf":"Südwestlich der Innenstadt, rund um die Stadtverwaltung Groß-Amman; frag einen Fahrer nach „Ras al-Ain“. Es ist ein gewöhnliches Stadtviertel ohne Ruinen – am schönsten als Spaziergang mit der Geschichte im Kopf. (Die App nutzt eine ungefähre Lage, deshalb ist der Check-in-Radius groß.)","1k7qqtb":"Jogbeha","tz07t":"Jubeiha, Nord-Amman (nahe der Universität von Jordanien)","1mme183":"Bevor Israel nach Kanaan kam, baute der Stamm Gad mehrere Städte östlich des Jordan, und Jogbeha war eine davon. Später verfolgte der Richter Gideon das Heer der Midianiter „östlich von Nobach und Jogbeha“ und schlug zu, als sich der Feind sicher fühlte. Dreitausend Jahre später hat sich der Name kaum verändert: Das heutige Jubeiha ist ein belebtes Wohnviertel im Norden Ammans, wo die Universität von Jordanien liegt.","10gi2ve":"Vielleicht kommst du jeden Tag an einem Ort vorbei, den die Bibel vor dreitausend Jahren erwähnte. Welche anderen „gewöhnlichen“ Orte um dich herum verbergen eine Geschichte?","n7y9q9":"🗺️ Aufgabe: Such „Jubeiha / الجبيهة“ auf einem Straßenschild und fotografier es. Vor dreitausend Jahren benutzten die Menschen fast denselben Namen!","hpoc84":"Welcher Richter kam bei der Verfolgung der Feinde an Jogbeha vorbei?","8fhm4o":"Simson","1p8o5f8":"Debora","tzsmyb":"Gideon","o72e60":"⚠️ Ein gewöhnliches Wohngebiet ohne Ruinen oder Besuchereinrichtungen. Im Norden Ammans – fahr zur Universität von Jordanien oder nach Jubeiha. Einchecken kannst du überall in der Gegend.","i0b1tj":"Abel-Keramim (Aue der Weinberge)","1u21hu1":"Lage unsicher; manche vermuten die Gegend von Sahab","y60zag":"Der Richter Jephta war von seiner Familie vertrieben worden, und doch kamen später die Ältesten Gileads und baten ihn, sie gegen die Ammoniter zu führen. Jephta schlug sie vernichtend, von Aroer bis Minnith und weiter bis „Abel-Keramim“ – „Aue der Weinberge“. Leider legte er vor der Schlacht ein voreiliges Gelübde ab und zahlte später einen herzzerreißenden Preis dafür (Richter 11). Wo dieser Ort genau lag, wissen die Gelehrten nicht; manche vermuten die Gegend von Sahab südöstlich von Amman – deshalb ist dies ein verborgenes Level.","17sq1bp":"Jephtas Sieg wurde von einem unüberlegten Versprechen überschattet. Hast du kürzlich im Eifer des Augenblicks etwas zugesagt, das du noch einmal durchdenken solltest?","18t417d":"🔒 Verborgene Aufgabe: Lies die ganze Geschichte in Richter 11 und komm dann zum Quiz zurück.","yyafsj":"Welcher Richter schlug die Ammoniter bis nach Abel-Keramim?","mg5djx":"Jephta","x6ie95":"Ehud","1wjkidq":"Othniel","ewnl7y":"Bethanien jenseits des Jordan (Taufstelle)","cjrab3":"Al-Maghtas, UNESCO-Welterbe","1l6xllt":"Johannes der Täufer rief in der Wüste östlich des Jordan zur Umkehr, und Scharen kamen aus Jerusalem herab, um sich taufen zu lassen. Auch Jesus kam hierher und wurde von Johannes getauft; der Himmel öffnete sich, und der Geist kam wie eine Taube herab. Später, als man ihn steinigen wollte, zog sich Jesus wieder „an den Ort, wo Johannes zuerst taufte“, zurück. Byzantinische Christen bauten hier mehrere Kirchen, deren Reste und Taufbecken Archäologen freigelegt haben. Seit 2015 ist der Ort Weltkulturerbe.","1ig3sro":"Bevor Jesus sein Wirken begann, wurde er hier getauft. Gab es in deinem Leben einen Moment des „Neuanfangs“?","17htpm":"📸 Aufgabe: Such den Holzsteg am Jordan und fotografier das Wasser. Das andere Ufer ist ein anderes Land, und der Fluss ist vielleicht viel schmaler, als du denkst!","1nyiwmd":"Wo taufte Johannes laut dem Johannesevangelium?","lv2jgu":"Am See Genezareth","12s6wj8":"In Bethanien jenseits des Jordan","1z0f7nc":"Am Teich Bethesda in Jerusalem","163gn3j":"Etwa 50 Minuten Fahrt von Amman Richtung Totes Meer; folge den Schildern „Baptism Site“. Tickets im Besucherzentrum kaufen, dann mit dem Shuttle samt Führung aufs Gelände – Privatautos dürfen nicht hineinfahren. Angemessene Kleidung (Schultern und Knie bedeckt). Im Sommer sehr heiß; Wasser und Hut mitnehmen. Tickets und Öffnungszeiten auf der offiziellen Seite baptismsite.com.","1urdagb":"Elias Hügel (Tell Mar Elias)","1h26wl6":"Auf dem Gelände der Taufstelle, am Wadi Kharrar","19lw334":"Elia und Elisa gingen zum Jordan. Elia schlug mit seinem Mantel auf das Wasser, der Fluss teilte sich, und sie gingen trockenen Fußes ans Ostufer. Während sie gingen und redeten, trennte sie ein feuriger Wagen mit feurigen Pferden, und Elia fuhr im Sturmwind auf zum Himmel. Die Bibel nennt den genauen Hügel nicht, aber seit byzantinischer Zeit erinnern Gläubige an dieses Ereignis auf diesem kleinen Hügel neben der Taufstelle, wo Reste eines Klosters und von Kirchen erhalten sind. Interessant: Johannes der Täufer kam „in dem Geist und der Kraft des Elia“ – und er taufte direkt neben dem Ort, an dem Elia gegangen war.","86y7g2":"Elisa bat um „ein zwiefältiges Teil“ von Elias Geist. Wenn du einen geistlichen Mentor um eine Sache bitten könntest, was wäre es?","1rifuky":"🔍 Aufgabe: Such in der Nähe des Hügels nach alten Becken oder Wasserkanälen. Wie kamen die Mönche hier an ihr Wasser?","1n734sx":"Womit schlug Elia auf das Wasser, um den Jordan zu teilen?","1p7yntp":"Mit seinem Stab","ze4xwn":"Mit seinem Mantel","81i7ap":"Mit einem Stein","18712t9":"Auf dem Gelände der Taufstelle; die Führung kommt daran vorbei oder in Sichtweite. Kein eigenes Ticket nötig. (Die App nutzt eine ungefähre Lage, deshalb ist der Check-in-Radius groß.)","3tludr":"Sittim (Israels letztes Lager)","1gea0bg":"Ausgrabungsstätte Tall el-Hammam","erzr88":"Sittim war Israels letztes Lager vor dem Zug über den Jordan. Von hier sandte Josua heimlich zwei Kundschafter nach Jericho, wo Rahab sie versteckte. Leider fiel das Volk auch in Sittim in Unzucht mit den Töchtern Moabs und betete den Baal-Peor an. Tall el-Hammam ist ein großer antiker Siedlungshügel im Jordantal, den viele Gelehrte mit Sittim gleichsetzen; manche halten ihn für Sodom, doch das ist sehr umstritten.","12ji2gw":"Derselbe Ort sah den Mut der Kundschafter und den Fall in den Götzendienst. Warum kann der Moment, der einer Verheißung am nächsten ist, auch der gefährlichste sein?","1kntjsj":"👀 Aufgabe: Stell dich auf den Hügel und schau nach Westen. Siehst du die Hügel jenseits des Jordantals? Dorthin waren die Kundschafter unterwegs.","1rzt60a":"Wie viele Kundschafter sandte Josua von Sittim aus?","92gzwp":"Zwei","gg6384":"Zwölf","1otzqn2":"Sieben","in8odj":"⚠️ Dies ist eine Ausgrabungsstätte ohne Besucherzentrum oder Einrichtungen; der Zugang ist nicht bestätigt. Sie liegt bei South Shuneh auf dem Weg von Amman zum Toten Meer. Geh mit jemandem, der sich auskennt, und betritt keine eingezäunten Grabungsbereiche.","uumqnh":"Die Ebenen Moabs","1vjkafy":"Jordantal nördlich des Toten Meeres","185vxng":"Nach dem Auszug aus Ägypten und vierzig Jahren in der Wüste lagerte Israel in den Ebenen Moabs, gegenüber von Jericho. Das ganze 5. Buch Mose ist Moses letzte Rede an das Volk in diesen Ebenen: Er wiederholt das Gesetz und ermahnt sie, Gott nie zu vergessen. Damals heuerte auch Balak, der König von Moab, Bileam an, um Israel zu verfluchen – doch jedes Mal, wenn Bileam den Mund öffnete, segnete er es. Heute sind die Ebenen voller Dattelpalmen und Höfe.","1btery":"Bevor das Volk ins Land kam, verwendete Mose ein ganzes Buch darauf, es zum „Gedenken“ zu ermahnen. Was ist eine Sache, die du nie vergessen willst?","nobgpu":"🌴 Aufgabe: Zähl beim Durchfahren, wie viele Dattelpalmenhaine du siehst.","1ai77mb":"Welches Buch enthält Moses Reden in den Ebenen Moabs?","1j9lsjd":"1. Mose (Genesis)","92cmvp":"3. Mose (Levitikus)","1gbmyoc":"5. Mose (Deuteronomium)","1hgoy19":"Dies ist eine ganze Region, durch die du auf dem Weg von Amman zum Toten Meer oder zur Taufstelle fährst. Einchecken kannst du überall in der Gegend.","1kxbocv":"Berg Nebo / Pisga","83sm3r":"Mose-Gedächtniskirche in Siyagha","719zyb":"Nachdem Mose das Volk vierzig Jahre geführt hatte, sagte Gott ihm, er solle auf den Berg Nebo steigen. Gott zeigte ihm das ganze verheißene Land und sagte dann: „Du sollst nicht hinübergehen.“ Mose starb im Land Moab, und Gott selbst begrub ihn; bis heute weiß niemand, wo sein Grab ist. Im 4. Jahrhundert bauten Gläubige auf dem Gipfel eine Kirche zum Gedenken an Mose, mit wunderschönen Mosaikböden. An klaren Tagen sieht man das Tote Meer, Jericho und sogar das ferne Jerusalem.","8jouvv":"Mose sah die Verheißung, betrat sie aber nicht. Gibt es etwas, wonach du dich sehnst, das du vielleicht an die nächste Generation weitergeben musst?","1my2zgk":"🐍 Aufgabe: Such auf dem Gipfel die Skulptur der ehernen Schlange und mach ein Foto. An welches Ereignis aus 4. Mose 21 erinnert sie?","hxui2m":"Wo ist laut dem 5. Buch Mose Moses Grab?","1kqgtuf":"Unter der Kirche auf dem Berg Nebo","1f8pq7v":"Bis heute weiß es niemand","15o2gxk":"In Jerusalem","1e6zwuc":"Etwa 10 km westlich von Madaba, rund 45 Minuten Fahrt von Amman. Auf dem Gipfel gibt es die Kirche, eine Aussichtsterrasse, einen Laden und Toiletten. Gut mit Madaba an einem Tag zu verbinden. Es ist windig – Jacke mitnehmen.","1qmmbks":"Medeba (Madaba)","1jms6k7":"Mosaikkarte in der Georgskirche","1e0blds":"Medeba ist ein biblischer Stadtname, der sich in dreitausend Jahren kaum verändert hat. Ihr größter Schatz ist eine Mosaikkarte aus dem 6. Jahrhundert auf dem Boden der griechisch-orthodoxen Georgskirche: über eine Million winziger Steinchen, die das Heilige Land zeigen, mit dem Jordan, dem Toten Meer und dem ummauerten Jerusalem. Sie ist eine der ältesten erhaltenen Karten des Heiligen Landes, und Archäologen haben mit ihr mehrere antike Orte lokalisiert. Deshalb heißt Madaba die „Stadt der Mosaike“.","fn1hb1":"Gläubige von damals setzten das Heilige Land, das sie kannten, Stein für Stein zusammen. Wenn du eine „Landkarte deines Glaubens“ zeichnen würdest, welche Orte wären darauf?","1ec3q":"🗺️ Aufgabe: Finde Jerusalem auf der Mosaikkarte (die ummauerte Stadt). Such dann die Fische im Jordan – in welche Richtung schwimmen sie?","joghvf":"Was ist Madabas berühmtester antiker Schatz?","2vt7xz":"Eine Mosaikkarte des Heiligen Landes","14kgke1":"Der Stab des Mose","1o13lwo":"Eine Pyramide","1yrzdl1":"Etwa 30 km südlich von Amman, rund 40 Minuten Fahrt; auch Taxi, Careem und Uber funktionieren. Von Amman fahren außerdem Minibusse – aktuelle Abfahrtsstationen vorher erfragen. Die Georgskirche liegt in der Innenstadt; Eintritt kostenpflichtig, während der Gottesdienste für Besucher geschlossen.","1fzf4u8":"Hesbon","kxtrn2":"Ausgrabungsstätte Tell Hisban","ew3e2q":"Hesbon war die Hauptstadt Sihons, des Königs der Amoriter. Als Israel um Durchzug bat, lehnte Sihon ab und griff an, wurde aber besiegt, und das Land fiel an die Stämme Ruben und Gad. Das Hohelied vergleicht die klaren Augen der Braut mit den „Teichen zu Hesbon“. Archäologen graben hier seit 1968 – und sie haben tatsächlich ein großes antikes Wasserbecken freigelegt.","ny89ca":"Das Hohelied preist die Geliebte mit den Teichen einer Stadt. Wann hast du den Menschen, der dir am nächsten ist, zuletzt ganz konkret gelobt?","y2o8j6":"💧 Aufgabe: Finde das antike Wasserbecken auf dem Gelände. Stell dir vor, wie die Teiche für den Dichter des Hohenliedes aussahen.","1ebdh4u":"Hesbon war die Hauptstadt welches Königs?","q0q840":"Balak von Moab","1ict2aa":"Sihon, König der Amoriter","y4yujx":"Og von Basan","7kv037":"Zwischen Amman und Madaba, neben dem Dorf Hisban, ein kleiner Abstecher von der Hauptstraße. Ein kleines Gelände mit wenigen Einrichtungen.","1drfpcy":"Beth-Peor (Moses Quellen)","y56wbo":"Ayun Musa, unterhalb des Berges Nebo","1d1xo7a":"Das 5. Buch Mose sagt, Gott habe Mose „im Tale, im Lande Moab, Beth-Peor gegenüber“ begraben. Die Quellen im Tal nördlich des Berges Nebo heißen Ayun Musa – arabisch für „Moses Quellen“ –, und hier gibt es Reste byzantinischer Kirchen. Wo genau Beth-Peor lag, ist unter Gelehrten nicht geklärt, aber dieses Tal liegt am Fuß des Berges, auf dem Mose zuletzt stand.","1abfcdh":"Niemand weiß, wo Moses Grab ist. Warum wollte Gott vielleicht nicht, dass man es findet?","1ox8dcf":"💦 Aufgabe: Such die Quelle und lausche dem Rauschen des Wassers.","1hihvx5":"Was bedeutet „Ayun Musa“?","1lel1m":"Moses Berg","4bsfh1":"Moses Quellen","1wufk0z":"Moses Haus","15eou9y":"Im Tal unterhalb des Berges Nebo; die Straße ist eng, also selbst fahren oder einen ortskundigen Fahrer fragen. Wenige Einrichtungen.","2dlf8b":"Elale","1pm3cdo":"Das Dorf El-Al","1iq3r1n":"Elale war eine der Städte, die der Stamm Ruben wieder aufbaute, ein Nachbar von Hesbon. Jahrhunderte später klagte Jesaja über Moab: „Hesbon und Elale schreien, bis Jahaz wird ihre Stimme gehört.“ Heute bewahrt der Dorfname El-Al noch den alten Namen.","1uwtsyj":"Jesaja weinte über Moab, Israels Feind. Könntest du um jemanden trauern, der dich nicht mag?","8src08":"🏘️ Aufgabe: Such von einem hohen Punkt im Dorf die Richtung nach Hesbon (nach Süden).","1mppkwx":"Mit welcher Stadt wird Elale oft zusammen genannt?","1h3jtpv":"Jericho","14ev346":"Damaskus","8b9ppi":"⚠️ Ein gewöhnliches Dorf ohne Besuchereinrichtungen, etwa 3 km nördlich von Hesbon. Bitte nimm Rücksicht auf die Bewohner und betritt kein Privatgelände.","o2i8df":"Baal-Meon","1juim1z":"Das Dorf Ma'in (nicht die heißen Quellen von Ma'in)","h4rtom":"Baal-Meon war eine weitere Stadt, die der Stamm Ruben baute und umbenannte. Später prahlte König Mesa von Moab auf seinem beschrifteten Stein, er habe Baal-Meon gebaut – die Stadt wechselte also mehr als einmal zwischen Israel und Moab den Besitzer. Im heutigen Dorf Ma'in wurden auch Mosaiken byzantinischer Kirchen gefunden. Hinweis: Es ist nicht derselbe Ort wie die beliebten heißen Quellen von Ma'in.","1fjxj1c":"Die Rubeniter benannten Städte um, die Namen heidnischer Götter trugen. Gibt es in deinem Leben etwas, das einen „neuen Namen“ braucht – eine neue Bestimmung?","kwxgek":"🧩 Aufgabe: Die Gegend um Madaba ist voller Mosaike. Vergleiche die, die du heute gesehen hast – welches gefällt dir am besten?","74qydy":"Welcher König behauptete auf einer Steininschrift, Baal-Meon gebaut zu haben?","1tbepx4":"König David","12qqsx2":"König Mesa von Moab","jb089u":"König Herodes","q3glnl":"Etwa 7 km südwestlich von Madaba, eine kurze Fahrt. Ein gewöhnliches Dorf mit wenigen Einrichtungen.","ibmfpt":"Machärus (wo Johannes der Täufer starb)","c10nok":"Ruinen einer Bergfestung beim Dorf Mukawir","r9373y":"Johannes der Täufer hielt Herodes Antipas ins Gesicht vor: „Es ist dir nicht erlaubt, die Frau deines Bruders zu haben.“ Da ließ Herodes ihn gefesselt ins Gefängnis werfen. Später, beim Geburtstagsfest des Herodes, tanzte die Tochter der Herodias und gefiel ihm; Herodes schwor leichtfertig, ihr alles zu geben, und auf Drängen ihrer Mutter verlangte sie den Kopf des Johannes. Obwohl betrübt, schickte Herodes einen Henker ins Gefängnis. Die Evangelien nennen das Gefängnis nicht, aber der jüdische Geschichtsschreiber Josephus aus dem 1. Jahrhundert sagt klar, dass Johannes in Machärus getötet wurde. Herodes der Große baute diese Festung auf einem Gipfel mit Blick aufs Tote Meer, und man sieht noch Säulen, die wieder aufgerichtet wurden.","1cabgwi":"Johannes sagte einem mächtigen Mann die Wahrheit und bezahlte mit seinem Leben; Herodes tat, um sein Gesicht zu wahren, was er selbst nicht wollte. Bist du öfter wie Johannes – oder wie Herodes?","1lqw8ll":"🌅 Aufgabe: Steig auf den Gipfel (etwa 15 Minuten) und schau nach Westen über das Tote Meer; an klaren Tagen sieht man die Hügel auf der anderen Seite. Stell dir vor, was Johannes in seinen letzten Tagen in einer Zelle hier dachte.","hkohfu":"Welcher Geschichtsschreiber berichtete, dass Johannes in Machärus getötet wurde?","l2zu9q":"Josephus","16jyrg0":"Herodot","nmmdzm":"Lukas","iyyvpk":"Etwa 40 Minuten Fahrt südwestlich von Madaba bis zum Dorf Mukawir, dann weiter zum Parkplatz am Fuß des Hügels. Der Aufstieg zum Gipfel dauert etwa 15 Minuten und ist etwas steil – gute Schuhe tragen. Oben gibt es keinen Schatten, also Wasser und Hut mitnehmen. Im Dorf gibt es eine Webkooperative von Frauen, die du unterwegs unterstützen kannst.","5zkszy":"Dibon (Fundort der Mescha-Stele)","7chrnx":"Der antike Hügel neben der Stadt Dhiban","90w282":"2. Könige berichtet, Mesa, der König von Moab, sei ein Herdenbesitzer gewesen und habe dem König von Israel jährlich einen riesigen Tribut an Lämmern und Wolle gezahlt; nach Ahabs Tod fiel Mesa ab. 1868 fand ein Missionar in Dibon einen schwarzen Basaltstein, auf den Mesa selbst seine Taten hatte meißeln lassen: Er sagt, Omri, der König von Israel, habe Moab unterdrückt, und er selbst habe später mehrere Städte zurückerobert. Der Stein nennt auch den Gott Israels und erwähnt möglicherweise das „Haus David“. Leider zerschlugen Einheimische ihn später; die Bruchstücke wurden gesammelt und zusammengesetzt, und heute steht er im Louvre in Paris. Er ist eines der antiken Zeugnisse außerhalb der Bibel, die den Bericht der Königsbücher am direktesten widerspiegeln.","o76am6":"Die Königsbücher und die Mescha-Stele berichten denselben Konflikt von zwei verschiedenen Seiten. Wenn die andere Person die Geschichte eines deiner letzten Konflikte schreiben würde, wie würde sie lauten?","1xtfjyc":"🪨 Aufgabe: Stell dich auf den Hügel und stell dir vor, wie der Stein 1868 irgendwo in der Nähe lag. Wenn du später das Jordan Museum in Amman besuchst, such dort die Nachbildung der Mescha-Stele.","qvur7x":"Wo wird die originale Mescha-Stele heute aufbewahrt?","xlslna":"In der Zitadelle von Amman","1bzqzs5":"Im Louvre in Paris","gfiyrx":"Im British Museum","1bvdtxk":"In der Stadt Dhiban, etwa 30 Minuten Fahrt südlich von Madaba auf der Königsstraße (Route 35). Der Hügel liegt neben der Stadt, mit einigen ausgegrabenen Resten und wenigen Einrichtungen. Gut mit Aroer und der Arnon-Schlucht zu verbinden.","3t77k9":"Mephaat (Umm ar-Rasas)","1ohtld7":"Umm ar-Rasas, UNESCO-Welterbe","1pk07eb":"Mephaat war eine Stadt, die Josua dem Stamm Ruben zuteilte, später eine Levitenstadt; auch Jeremia sagte ihr das Gericht an. In der Stephanuskirche legten Archäologen einen riesigen Mosaikboden aus dem 8. Jahrhundert frei, der Städte des Heiligen Landes und östlich des Jordan zeigt – eine davon trägt die Aufschrift „Kastron Mefaa“, was beweist, dass dies das biblische Mephaat ist. Neben den Ruinen steht ein über ein Dutzend Meter hoher Steinturm, auf dessen Spitze einst ein Mönch allein im Gebet lebte. Seit 2004 ist der Ort Weltkulturerbe.","6bp1zn":"Mönche stiegen früher auf einen Turm, um den Lärm hinter sich zu lassen und zu beten. Gibt es in deinem Leben einen „Turm“, auf dem du still werden kannst?","1xm6dem":"🗺️ Aufgabe: Such auf dem Mosaikboden der Stephanuskirche die Bilder ummauerter Städte und schau, wie viele Städtenamen du erkennst.","s4yytb":"Wie bestätigten Archäologen, dass dies Mephaat ist?","1gzhl8e":"Sie fanden ein Schwert mit dem eingravierten Namen","wwg9m9":"Ein Mosaikboden beschriftet die Stadt mit ihrem Namen","v6ecph":"Die Einheimischen nannten sie immer so","1fttmwr":"Etwa 30 km südöstlich von Madaba, rund 40 Minuten Fahrt. Es gibt ein Besucherzentrum und Eintritt (Jordan Pass gilt). Die Mosaike liegen unter einem Schutzdach. Das Gelände ist groß und hat fast keinen Schatten – Wasser und Hut mitnehmen.","u0tyr5":"Aroer (am Rand des Arnon)","dr141y":"Beim Dorf Ara'ir, am Nordrand der Arnon-Schlucht","vljn1m":"Aroer lag am Nordrand der Arnon-Schlucht, der Südgrenze Israels östlich des Jordan. Mose sagte: „Von Aroer, das am Ufer des Flusses Arnon ist … war keine Stadt, die uns zu hoch gewesen wäre.“ Interessant: Auch die Mescha-Stele erwähnt diese Stadt – Mesa sagt, er habe „Aroer gebaut und die Straße am Arnon angelegt“. Eine Stadt, die sowohl in der Bibel als auch auf dem Stein des moabitischen Königs genannt wird.","1z0g1ek":"Der Blick vom Rand hinunter macht Angst, und doch sagte Mose, keine Stadt sei zu hoch gewesen. Was vor dir sieht gerade zu hoch oder zu schwer aus?","1j16gwe":"🏞️ Aufgabe: Geh zu einer sicheren Stelle nahe am Rand und schau hinunter in die Arnon-Schlucht. (Halte Abstand zu Kanten ohne Geländer.)","tj4fj2":"Welches antike Fundstück außer der Bibel erwähnt Aroer?","1f849dl":"Die Mescha-Stele","ibhhyf":"Die Schriftrollen vom Toten Meer","1k4zm5e":"Die Madaba-Karte","16d1m3l":"⚠️ Eine kleine Ruine beim Dorf Ara'ir südlich von Dhiban, kurz bevor die Königsstraße in die Arnon-Schlucht hinabführt; keine Besuchereinrichtungen. Park sicher abseits der Straße und halte Abstand zur Felskante.","czt9d1":"Die Arnon-Schlucht (Wadi Mujib)","etrywi":"Die große Schlucht, die die Königsstraße durchquert; flussabwärts liegt das Mujib-Naturreservat","72xi7l":"Der Arnon war die Grenze zwischen Moab und den Amoritern. Als Israel auf seiner Wüstenwanderung dorthin kam, sagte Gott: „Macht euch auf, brechet auf und gehet über den Fluss Arnon“ – der Beginn der Landnahme östlich des Jordan. Die Schlucht ist so tief und breit, dass man sie „Jordaniens Grand Canyon“ nennt; die Königsstraße (Route 35) windet sich bis zum Grund hinab, überquert einen Damm und steigt auf der anderen Seite wieder an. Wo die Schlucht aufs Tote Meer trifft, liegt das Mujib-Naturreservat, eines der tiefstgelegenen Naturreservate der Erde, mit Wegen, auf denen man durchs Wasser die Schlucht hinaufwatet.","nvb526":"„Macht euch auf, brechet auf und gehet über den Fluss Arnon“ – war die Grenze einmal überschritten, gab es kein Zurück. Gibt es einen „Arnon“ in deinem Leben, den du mutig überqueren musst?","solzc4":"🚗 Aufgabe: Halte bei der Fahrt auf der Königsstraße in die Schlucht an einem sicheren Aussichtspunkt und zähl, wie viele Farben von Gesteinsschichten du in den Felswänden siehst.","1jgn5qm":"Zwischen welchen beiden Völkern war der Arnon die Grenze?","1s9yve6":"Moab und den Amoritern","1rm1ra7":"Edom und Israel","xgqeol":"Ammon und den Philistern","1n84cnb":"Diese Station hat zwei Check-in-Bereiche – beide zählen: ① die Aussichtspunkte und der Damm, wo die Königsstraße (Route 35) südlich von Dhiban in die Schlucht hinabführt; ② das Besucherzentrum des Mujib-Naturreservats an der Totes-Meer-Straße (Schluchtwege vorher buchen; am schönsten im Sommer, im Winter bei hohem Wasser evtl. geschlossen). Die Straße in der Schlucht ist kurvig – langsam fahren. (Ungefähre Lage, deshalb ist der Check-in-Radius groß.)","1x6ezet":"Kallirrhoë (Zereth-Schachar)","8guy2v":"Die heißen Quellen von Ez-Zara am Ostufer des Toten Meeres","1y0nonn":"Josua teilte dem Stamm Ruben „Zereth-Schachar auf dem Berge des Tales“ zu, und viele Gelehrte verorten es an diesen heißen Quellen am Ostufer des Toten Meeres. Zur Zeit des Neuen Testaments hieß der Ort Kallirrhoë („schön fließend“). Josephus berichtet, dass Herodes der Große, schwer krank und dem Tod nahe, hierherkam, um in den heißen Quellen Heilung zu suchen – ohne Besserung. Auch die Mosaikkarte von Madaba zeigt den Ort: Quellen und Palmen am Ufer des Toten Meeres. In den Bergen in der Nähe liegt Machärus, wo sein Sohn später Johannes den Täufer gefangen hielt.","11c03iy":"König Herodes hatte genug Macht und Geld, um sich die besten heißen Quellen zu leisten, aber Gesundheit und Frieden konnte er nicht kaufen. Was soll bei dir das Geld lösen, was Geld in Wahrheit nicht lösen kann?","11t0mlp":"♨️ Aufgabe: Finde die Stelle, wo das heiße Quellwasser zum Toten Meer fließt, und fühl, wie warm es ist (Vorsicht – es kann heiß sein).","1jb52w6":"Welcher König kam vor seinem Tod nach Kallirrhoë, um zu baden?","1rum82h":"Herodes der Große","17nlz75":"König Salomo","1s0pz2":"König Mesa","ovuqcd":"An der Totes-Meer-Straße, etwa 30 Minuten Fahrt südlich des Hotelgebiets am Nordende des Toten Meeres. Bei den Quellen gibt es eine private Anlage, manche Bereiche kosten Eintritt. Die Straße am Toten Meer ist sehr heiß – im Sommer mittags nicht lange verweilen.","xn2tyf":"Ataroth (Khirbet Ataruz)","pwnh1f":"Hügelruinen nahe Machärus","17mivk0":"Der Stamm Gad baute Ataroth östlich des Jordan. Die Mescha-Stele sagt: „Die Männer von Gad wohnten seit jeher im Land Ataroth“, und dass Mesa die Stadt später eroberte. Archäologen legten hier einen Tempel aus moabitischer Zeit und einen Altar mit alter Inschrift frei – so lassen sich Bibel, Mescha-Stele und Archäologie direkt nebeneinander vergleichen.","dqvh43":"Dasselbe Land wechselte mehrmals den Besitzer. Welche Dinge, die du jetzt „besitzt“, sind dir in Wahrheit nur für eine Zeit anvertraut?","p1mm89":"🔭 Aufgabe: Versuch, von hier aus den Gipfel von Machärus zu entdecken.","1dsf14u":"Welcher Stamm baute Ataroth?","yxek91":"Juda","15sm38z":"Gad","1wbybqd":"Benjamin","vqyxc3":"⚠️ Eine Ausgrabungsstätte ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt. Sie liegt ein kurzes Stück östlich des Dorfes Mukawir – gut mit Machärus zu verbinden.","5x4ey8":"Jahaz (König Sihons letzte Schlacht)","1lklvpj":"Lage unsicher, möglicherweise nordöstlich von Dhiban","iai6k8":"Israel bat Sihon, den König der Amoriter, höflich um Durchzug und versprach, weder Felder zu betreten noch aus Brunnen zu trinken, sondern nur auf der Königsstraße zu ziehen. Sihon lehnte nicht nur ab, sondern zog sein ganzes Heer in der Wüste zusammen und kämpfte bei Jahaz gegen Israel – und wurde vernichtend geschlagen, und Israel nahm das Land vom Arnon bis zum Jabbok ein. Auch die Mescha-Stele erwähnt später Jahaz und sagt, Mesa habe es zurückerobert. Die genaue Lage ist bis heute unsicher, deshalb ist dies ein verborgenes Level.","120slyd":"Israel fragte zuerst höflich; der Konflikt kam erst nach der Ablehnung. Redest du vor einer Reibung mit jemandem zuerst klar und fragst freundlich?","nerke8":"🔒 Verborgene Aufgabe: Lies 4. Mose 21,21–35 und komm dann zum Quiz zurück.","yfjpj1":"Welchen König besiegte Israel bei Jahaz?","mfpqcc":"Og, König von Basan","1grve39":"Sihon, König der Amoriter","bq5xf7":"Balak, König von Moab","siu44f":"Kir-Hareset (Burg Kerak)","1ilbskt":"Die Kreuzfahrerburg auf dem Hügel der Stadt Kerak","1mmz6j9":"Kerak ist Kir-Hareset, die Festung Moabs. Die Könige von Israel, Juda und Edom verbündeten sich gegen Moab und verwüsteten das Land, bis nur noch diese Stadt stand. König Mesa von Moab versuchte mit siebenhundert Schwertkämpfern einen Ausbruch und scheiterte. Ohne Ausweg opferte er seinen erstgeborenen Sohn, den Thronerben, als Brandopfer auf der Stadtmauer, und Israel zog ab und kehrte heim. Lange davor, als Saul ihn jagte, ging David nach „Mizpe-Moab“ und bat den König von Moab, sich um seinen Vater und seine Mutter zu kümmern; manche Gelehrte meinen, dieses Mizpe sei dieser Ort gewesen. Vielleicht wandte sich David an Moab, weil seine Urgroßmutter Ruth eine Moabiterin war. Die gewaltige Burg auf dem Hügel wurde 1142 von den Kreuzfahrern gebaut und später von Saladin und den Mamluken übernommen und erweitert.","el9tq5":"Der Prophet Jesaja kündigte Moab das Gericht an, und doch sagte er: „Mein Inneres klagt um Moab wie eine Laute“ – Gott trauert sogar um Feinde. Gibt es jemanden, den du schwer lieben kannst und den du versuchen könntest, mit Gottes Augen zu sehen?","1cjyico":"🏰 Aufgabe: Geh zur Mauer und schau nach Westen; an klaren Tagen sieht man das Tote Meer. Stell dir Mesa auf der Stadtmauer vor, umringt von den Heeren dreier Königreiche, und wie verzweifelt er gewesen sein muss.","1bzmdmc":"Wen bat David, sich um seine Eltern zu kümmern?","1jo8m95":"Den König von Edom","1jerurj":"Den König von Moab","k6prwc":"Den König von Ammon","4cokkr":"Etwa 2 Stunden Fahrt südlich von Amman (der Desert Highway ist schneller; die Königsstraße führt an den Orten von Kapitel 6 vorbei). Besucherzentrum und Eintritt (Jordan Pass gilt). Die Burg hat viele lange, dunkle Gänge – Taschenlampe mitnehmen oder das Handy benutzen und auf den unebenen Boden achten. In den Straßen draußen gibt es Restaurants fürs Mittagessen.","soext3":"Die Gefilde Moabs (Ruths Heimat)","ns5ds3":"Die Hochebene Moabs zwischen der Arnon-Schlucht und Kerak","1yniv7d":"In den Tagen der Richter kam eine Hungersnot über Bethlehem, und Elimelech zog mit seiner Frau Noomi und ihren zwei Söhnen in „die Gefilde Moabs“. Die Söhne heirateten moabitische Frauen, Orpa und Ruth, dann starben alle drei Männer. Noomi beschloss, nach Bethlehem zurückzukehren, und drängte ihre Schwiegertöchter, zu ihren Familien heimzugehen. Orpa ging unter Tränen, aber Ruth hielt an ihrer Schwiegermutter fest und gab eines der bewegendsten Versprechen der Bibel: „Wo du hingehst, will ich hingehen … dein Volk ist mein Volk, und dein Gott ist mein Gott.“ Ruth heiratete später Boas und wurde die Urgroßmutter von König David, und Matthäus schreibt ihren Namen sogar in den Stammbaum Jesu. Die Bibel sagt nicht, in welcher Stadt Moabs sie lebten, deshalb zählt die ganze Hochebene Moabs.","xkni0q":"Ruth war Ausländerin und Witwe mit ungewisser Zukunft, und doch entschied sie sich, bei Noomi zu bleiben. Gibt es in deiner Nähe jemanden, dem es schlecht geht und der dich sagen hören muss: „Ich gehe mit dir“?","wnzehf":"🌾 Aufgabe: Halte an einem Feld auf der Hochebene Moabs, lies Ruth 1,16–17 und fotografier die Felder. Als Ruth und Noomi nach Bethlehem kamen, war es „im Anfang der Gerstenernte“.","58gg28":"Ruth war die Urgroßmutter welches Königs von Israel?","12i2733":"König Saul","1pcom1g":"Kein bestimmter Punkt nötig: Wenn du auf der Königsstraße (Route 35) vom Südrand der Arnon-Schlucht Richtung Kerak fährst, bist du die ganze Zeit auf der Hochebene Moabs, und jeder Ort in der Gegend zählt. Am grünsten sind die Weizenfelder im Frühling (März–April). Wenn du für Fotos am Straßenrand hältst, such dir eine sichere Stelle und achte auf den Verkehr.","1sc5gsi":"Ar (den Nachkommen Lots gegeben)","1aif86g":"Die Ruinen von Khirbet al-Balu'a östlich der Königsstraße","i4inm5":"Als Israel aus der Wüste nach Norden an Moab vorbeizog, gab Gott Mose einen klaren Befehl: „Befeinde Moab nicht und laß dich nicht in Streit mit ihnen ein“, denn er hatte Ar den Kindern Lots gegeben. Die Moabiter stammten von Lot ab; Gott hatte Lot nicht vergessen und sorgte auch für seine Nachkommen. Viele Gelehrte halten die große Ruine hier bei Balu'a für Ar. Hier wurde eine antike Stele gefunden, die einen König zwischen zwei Göttern zeigt – ein wichtiges Zeugnis der moabitischen Zeit, das heute in einem Museum in Amman steht.","yndr7h":"Gott sagte Israel, es solle Moabs Land nicht nehmen, obwohl es das gekonnt hätte. Wenn du die Macht hast, um etwas zu kämpfen, dich aber entscheidest nachzugeben – was geht dann in deinem Herzen vor?","ncuq9p":"🔭 Aufgabe: Schau von den Ruinen nach Norden Richtung Arnon-Schlucht. Irgendwo hier zog Israel an den moabitischen Städten vorbei, ohne sie anzugreifen.","1g3de75":"Warum sagte Gott Israel, es solle nicht gegen Moab kämpfen?","pjdyho":"Moab war zu stark","92sac":"Gott hatte Ar den Nachkommen Lots gegeben","j3ms6r":"Israel hatte sich verirrt","p6lv5c":"⚠️ Eine Ausgrabungsstätte ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt. Sie liegt ein Stück östlich der Königsstraße, nicht weit südlich der Arnon-Schlucht – gut am selben Tag mit der Hochebene Moabs und Kerak zu verbinden.","1d0qzx":"Lots Höhle (Kloster des heiligen Lot)","523nvg":"Ruinen eines byzantinischen Klosters an einem Hang bei Ghor es-Safi","10yhf69":"Nach der Zerstörung Sodoms floh Lot zuerst nach Zoar, fürchtete sich aber, in der Stadt zu bleiben; so ging er mit seinen beiden Töchtern ins Gebirge hinauf und wohnte in einer Höhle. Weil sie meinten, es gebe keinen Mann mehr auf der Erde, taten die Töchter etwas zutiefst Falsches, und jede bekam einen Sohn: Moab, den Vater der Moabiter, und Ben-Ammi, den Vater der Ammoniter. Byzantinische Christen glaubten, dies sei die Höhle, und bauten neben dem Eingang ein Kloster und eine Kirche mit Mosaikinschriften, die den „heiligen Lot“ nennen. Auch die Mosaikkarte von Madaba zeigt dieses Heiligtum. Das Museum am tiefsten Ort der Erde am Fuß des Hügels zeigt Funde von hier.","hr7h99":"Lots Familie entkam Sodom, aber Sodoms Einfluss blieb bei ihnen. Gibt es einen Ort oder eine Gewohnheit, die du hinter dir gelassen hast, die dich aber noch immer prägt?","15iycig":"⛰️ Aufgabe: Steig zum Kloster hinauf, such den Eingang der Höhle und schau hinunter auf die Ebene am Südende des Toten Meeres.","1fi0fqe":"Moab, der Sohn von Lots älterer Tochter, war der Stammvater welches Volkes?","1jotgn6":"Der Moabiter","1nmtsig":"Der Edomiter","52in9k":"Der Philister","1arks8v":"Am südlichen Abschnitt der Totes-Meer-Straße, kurz nördlich der Stadt Ghor es-Safi. Navigier zuerst zum Museum am tiefsten Ort der Erde; das Kloster liegt am Hang dahinter, eine steile Treppe hinauf (etwa 10–15 Minuten). Dies ist einer der tiefsten Orte der Erde und extrem heiß – im Sommer die Mittagszeit meiden und viel Wasser mitnehmen. Die Koordinaten sind ungefähr, achte also beim Näherkommen auf Schilder.","x9ym8u":"Zoar (die kleine Stadt, in die Lot floh)","16zzqh8":"Die Stadt Ghor es-Safi am Südende des Toten Meeres","xkowwl":"Die Engel drängten Lot, ins Gebirge zu fliehen, doch Lot bat: „Siehe doch, diese Stadt ist nahe, um dahin zu fliehen, und sie ist klein; laß mich doch dahin mich retten – ist sie nicht klein?“ Die Engel willigten ein, und so hieß die Stadt Zoar, „klein“. Die Sonne ging auf, als Lot nach Zoar kam, und dann wurde Sodom zerstört. Früher, als Lot sein Land wählte, sah er, dass die Ebene des Jordan „ganz bewässert war … bis nach Zoar hin“. In byzantinischer Zeit hieß die Stadt Zoora, und die Mosaikkarte von Madaba zeigt sie zwischen Palmen. Heute ist Ghor es-Safi noch immer ein Meer aus Feldern mit Tomaten und Bananen.","17rocu7":"Lot zog dorthin, wo das Land am reichsten aussah, und zog sich am Ende in eine kleine Stadt und dann in eine Höhle zurück. Wenn du Entscheidungen triffst, schaust du mehr auf den unmittelbaren Vorteil oder auf die langfristige Richtung?","133sn9y":"🍅 Aufgabe: Schau dir die Felder um dich herum an und vergleiche sie mit den kahlen Hügeln am Toten Meer. Stell dir vor, so ähnlich sah das „bewässerte“ Land aus, das Lot sah.","z5t4y":"Was bedeutet der Name „Zoar“?","idlyg1":"Salz","nke3fl":"Klein","1ng89l8":"Quelle","av8rnq":"Am südlichen Abschnitt der Totes-Meer-Straße, etwa 1 Stunde 15 Minuten Fahrt südlich des Hotelgebiets am Nordende des Toten Meeres. Die Stadt hat Tankstellen und kleine Läden. Verbinde es mit Lots Höhle und dem Museum am tiefsten Ort der Erde, und fahr dann nach Osten in die Berge nach Kerak (etwa 1 Stunde).","1jl5ocn":"Sodom und Gomorra","17cnl9r":"Lage unsicher, möglicherweise am Süd- oder Nordende des Toten Meeres","1vvd2wq":"Die Sünde Sodoms war schwer, und Gott beschloss, die Stadt zu zerstören. Abraham trat bei Gott für die Stadt ein, und Gott sagte zu, sie nicht zu zerstören, wenn sich auch nur zehn Gerechte darin fänden. Es gab nicht einmal zehn. Die Engel nahmen Lots Familie bei der Hand und führten sie hinaus, und sagten ihnen, sie sollten nicht zurückschauen. Doch Lots Frau schaute zurück und wurde zur Salzsäule. Jesus warnte später seine Jünger: „Gedenket an Lots Weib!“ Wo Sodom und Gomorra wirklich lagen, ist bis heute umstritten: Die Tradition verortet sie am Südende des Toten Meeres, andere plädieren für das Nordende, etwa Tall el-Hammam (Sittim in Kapitel 4). Deshalb ist dies ein verborgenes Level. Das Foto zeigt eine Salzfelssäule am Westufer des Toten Meeres, die die Leute „Lots Frau“ nennen.","gdp4qm":"Lots Frau hatte die Stadt mit den Füßen verlassen, aber ihr Herz war noch in Sodom. Gibt es etwas, das Gott dich loszulassen bittet, nach dem du dich aber immer wieder umschaust?","1ku14vx":"🔒 Verborgene Aufgabe: Lies 1. Mose 18,16–19,29 und komm dann zum Quiz zurück.","i86fat":"Was wurde aus Lots Frau, als sie zurückschaute?","1q1d8lf":"Eine Salzsäule","xr8kc4":"Ein Baum","11bs4ei":"Der Bach Sered (Wadi al-Hasa)","1ovlgk8":"Die große Schlucht an der Grenze zwischen Moab und Edom, die die Königsstraße durchquert","91u5he":"Der Sered war der Grenzbach am Südrand Moabs; dahinter lag Edom. Gott sagte zu Israel: „Nun machet euch auf und ziehet über den Bach Sered.“ Dann fügte Mose einen ernsten Satz hinzu: Vom Aufbruch aus Kades-Barnea bis zum Übergang über den Sered vergingen achtunddreißig Jahre – bis die ganze Generation der Kriegsmänner gestorben war, die sich geweigert hatte, Gott zu vertrauen und nach Kanaan hineinzuziehen. Mit anderen Worten: Das Erreichen dieses Baches markierte das eigentliche Ende der Wüstenwanderung, als eine neue Generation sich auf den Weg ins verheißene Land machte. Heute heißt die Schlucht Wadi al-Hasa; die Königsstraße windet sich bis zum Grund hinab und wieder hinauf, und die Schlucht mündet am Südende des Toten Meeres nahe Zoar.","1oo4iyt":"Achtunddreißig Jahre im Kreis gehen, bevor man diesen Bach erreichte. Gibt es eine Strecke in deinem Leben, auf der du lange „umhergeirrt“ bist? Was hat Gott dich im Rückblick auf diesem Weg gelehrt?","13qmhxx":"🏞️ Aufgabe: Such bei der Abfahrt auf der Königsstraße eine sichere Stelle zum Anhalten und schau, wie tief die Schlucht ist. Stell dir Hunderttausende Israeliten mit ihren Herden vor, die hier hinunter- und wieder hinaufsteigen.","uq7ed2":"Wie viele Jahre vergingen von Kades-Barnea bis zum Übergang über den Sered?","qfr8ws":"Sieben Jahre","1vqdj6x":"Achtunddreißig Jahre","1g132np":"Vierzig Jahre","192u5qj":"Von Kerak etwa 40 Minuten auf der Königsstraße (Route 35) nach Süden; die Straße führt zum Grund der Schlucht hinab und an der Südseite wieder hinauf, die ganze Strecke zählt. Der andere Stempelpunkt ist die Mündung der Schlucht an der südlichen Totes-Meer-Straße nahe Ghor es-Safi – gut mit Zoar und Lots Höhle zu verbinden. Die Bergstraße ist steil und kurvig, also langsam fahren.","awyqry":"Bozra (Hauptstadt Edoms)","1d5ipvi":"Ruinen der edomitischen Königsstadt beim Dorf Busayra","4m8pc8":"Die Edomiter stammten von Esau ab. Esau verkaufte einst sein Erstgeburtsrecht für eine Schüssel rotes Gericht, deshalb hieß er auch Edom, „rot“. Bozra war die wichtigste Stadt Edoms; einer der edomitischen Könige in der Liste des 1. Buches Mose kam aus Bozra. Die Propheten nannten oft Bozra stellvertretend für ganz Edom, und Jesaja 63 malt ein eindrückliches Bild: „Wer ist dieser, der von Edom kommt, von Bozra, in hochroten Kleidern?“ Es ist ein siegreicher Kämpfer, der zurückkehrt, nachdem er seinem Volk Recht verschafft hat – eine Stelle, die viele Christen auf den Messias hin lesen. In den 1970er-Jahren legten Archäologen hier einen Palast und einen Tempel aus edomitischer Zeit frei, was bestätigt, dass dies einst Edoms Hauptstadt war.","qozgu":"Esau gab einen bleibenden Segen für einen Augenblick Hunger auf. Warst du kürzlich versucht, etwas Wichtiges gegen eine „Schüssel Linsen“ direkt vor dir einzutauschen?","fcfucv":"🔴 Aufgabe: Schau dir die Farbe der Felsen und der Erde rund um die Ruinen an und such die „röteste“ Stelle. Der Name Edom („rot“) passt zu den roten Bergen dieser Gegend.","1v5cxph":"Was bedeutet der Name „Edom“?","19d4ccc":"Rot","1iq2nya":"Berg","170fe2i":"Erstgeborener","pt43tw":"Im Dorf Busayra, etwa 20 Minuten Fahrt südlich von Tafila auf der Königsstraße. Die Ruinen liegen direkt beim Dorf, ohne Besucherzentrum oder Ticket; man sieht Steinmauern und Grundmauern von Räumen. Das Biosphärenreservat Dana liegt ein Stück westlich, sodass man beides an einem Tag verbinden kann.","u3pdmn":"Tophel (Tafila)","1ya7ecl":"Die Stadt Tafila im edomitischen Hochland","32ibxe":"Das 5. Buch Mose beginnt mit den Worten, die Mose zu ganz Israel in der Wüste jenseits des Jordan redete, „zwischen Paran und Tophel und Laban und Hazeroth und Di-Sahab“. Tophel kommt nur ein einziges Mal in der Bibel vor. Weil der Name so sehr nach dem heutigen Tafila klingt, halten manche dies für den Ort, aber die Gelehrten haben es nicht geklärt. Tafila ist eine Bergstadt im Süden Jordaniens, umgeben von Olivenhainen, und im Winter schneit es hier manchmal sogar.","1jjtqqq":"Tophel kommt nur einmal in der Bibel vor, und doch wurde es aufgeschrieben. In Gottes Geschichte ist kein Ort und kein Mensch überflüssig. Wo fühlst du dich übersehen? Sieht Gott es?","1ciqc0a":"🫒 Aufgabe: Such in Tafila einen Olivenhain, oder trink in einem kleinen Laden im Ort einen Tee und unterhalte dich mit Einheimischen über den Namen der Stadt.","15zfrod":"Wie oft kommt der Name Tophel in der Bibel vor?","4wvbok":"Einmal","1cxqqk8":"Siebenmal","44rql7":"Fünfzigmal","2nnx86":"Etwa 1 Stunde südlich von Kerak auf der Königsstraße (nach der Sered-Schlucht bergauf). Tafila ist eine Provinzhauptstadt mit Tankstellen, Restaurants und Läden – ein guter Ort für eine Pause und das Mittagessen. ⚠️ Ob Tophel Tafila ist, ist nicht geklärt; dieser Stempel erinnert an die ersten Zeilen des 5. Buches Mose.","1awho6j":"Sela (Edoms Felsenfestung)","1l0die5":"Die Felsbergfestung beim Dorf as-Sela","a5pijp":"„Sela“ bedeutet „Fels“. Amazja, der König von Juda, erschlug im Salztal zehntausend Edomiter, nahm dann Sela ein und nannte es Joktheel. Dieser Felsberg ist fast vollständig von Steilwänden umgeben, nur eine einzige in eine Felsspalte gehauene Treppe führt hinauf – kein Wunder, dass der Prophet Obadja Edom beschrieb als „der du in Felsenklüften, auf hohem Sitze wohnst“, in der Meinung, niemand könne es herabstürzen. Hoch oben an der Felswand befindet sich ein Relief mit Inschrift von Nabonid, dem letzten König Babylons, um das 6. Jahrhundert v. Chr. gemeißelt; Forscher mussten sich an Seilen abseilen, um es zu untersuchen.","ru71mo":"Edom meinte, hoch oben auf dem Felsen sei es sicher. Auf welchen „Felsen“ baust du dein Sicherheitsgefühl am häufigsten – Ersparnisse, Fähigkeiten, Beziehungen oder Gott?","1cuupp1":"🧗 Aufgabe: Betrachte den ganzen Felsberg von der Dorfseite aus und such, wo die Treppe in der Spalte beginnt. Wenn du scharfe Augen hast, versuch Nabonids Relief an der Felswand zu entdecken.","o9hxin":"Was bedeutet der Name „Sela“?","1fop1as":"Fels","1xia3gi":"Turm","81a5eu":"⚠️ Keine Besuchereinrichtungen; Zugang und Zustand nicht bestätigt. Es liegt zwischen Tafila und Bozra – von der Königsstraße nach Westen ins Dorf as-Sela abbiegen. Der einzige Weg hinauf ist eine antike Treppe in einer Felsspalte, steil und schmal; nicht allein hinaufsteigen und Regentage meiden. Den Felsen vom Dorf aus zu sehen, reicht für den Stempel.","1ggty5l":"Punon (das Kupfertal von Feinan)","18ivpvg":"Die Ruinen von Khirbet Faynan auf der Ostseite des Araba-Tals","158od97":"Eine der Stationen auf Israels Wüstenwanderung ist Punon. Hier lag eines der größten Kupferabbaugebiete des alten Orients, und das Tal ist bis heute mit schwarzer Kupferschlacke übersät. 4. Mose 21 berichtet, dass das Volk, als es Edom umging, ungeduldig wurde und gegen Gott redete, und feurige Schlangen kamen ins Lager; auf Gottes Befehl machte Mose eine eherne Schlange und setzte sie auf eine Stange, und jeder Gebissene, der sie ansah, blieb am Leben. Die Bibel sagt nicht, wo die Schlange gemacht wurde, aber weil Punon auf dieser Route lag und reich an Kupfer war, vermuten manche Gelehrte einen Zusammenhang. Jesus sagte später: „Gleichwie Moses in der Wüste die Schlange erhöhte, also muss der Sohn des Menschen erhöht werden.“ In römischer Zeit hieß der Ort Phaeno, und der Geschichtsschreiber Eusebius berichtet, dass Christen wegen ihres Glaubens zur Zwangsarbeit in seinen Kupferminen verurteilt wurden und manche hier den Märtyrertod starben.","ys678d":"Die Gebissenen mussten nichts Großes tun – sie mussten nur hinschauen. Versuchst du oft, Dinge aus eigener Kraft zu richten, und vergisst dabei, aufzuschauen?","5j9fz4":"⚒️ Aufgabe: Such auf dem Boden nach schwarzer, glasiger Kupferschlacke (nur anschauen – nichts mitnehmen) und stell dir die Menschen vor, die hier über Jahrtausende Kupfer abbauten und schmolzen.","19bsyh6":"Was erhöhte Mose in der Wüste?","1s9jw3m":"Einen Stab","19p7kiv":"Eine eherne Schlange","2co4ne":"Die Bundeslade","5n9n3h":"⚠️ Keine Besuchereinrichtungen an den Ruinen, und der Straßenzustand ist nicht bestätigt. Von der südlichen Totes-Meer-Straße (Wadi Araba) nach Osten ins Dorf Qurayqira abbiegen; das letzte Stück ist eine unbefestigte Schotterpiste, schwierig für normale Autos. Die nahe Feynan Ecolodge kann einen 4x4-Transport organisieren – vorher Kontakt aufnehmen. Im Sommer ist das Tal extrem heiß, Herbst oder Winter sind besser; viel Wasser mitnehmen.","veugwx":"Teman (Edoms Land der Weisheit)","1yfwkb3":"Lage unsicher, möglicherweise in der Gegend von Bozra","xkbmo5":"Teman war ein Enkel Esaus, und sein Name wurde später zum Namen einer Region Edoms. Teman war berühmt für seine Weisheit; der Prophet Jeremia fragte: „Ist keine Weisheit mehr in Teman?“ Als Hiob litt, war der erste der drei Freunde, die ihn trösten kamen, „Eliphas, der Temaniter“. Eliphas saß zuerst sieben Tage schweigend bei Hiob, doch dann beharrte er immer wieder darauf, Hiob müsse gesündigt haben, um so zu leiden; am Ende sagte Gott, sie hätten nicht recht von ihm geredet. Die genaue Lage Temans ist unsicher, deshalb ist dies ein verborgenes Level.","v5lmp8":"Eliphas' bester Trost waren die ersten sieben Tage, in denen er schweigend bei Hiob saß. Wenn ein Freund leidet, gibst du schnell Antworten – oder bist du bereit, zuerst einfach bei ihm zu bleiben?","gyccsp":"🔒 Verborgene Aufgabe: Lies Hiob 2,11–13 und 42,7–9 und komm dann zum Quiz zurück.","1c3gzn0":"Welcher von Hiobs Freunden kam aus Teman?","1knseko":"Eliphas","1xqwlap":"Bildad","vzg4lp":"Zophar","1aq518g":"Petra (Hauptstadt des Nabatäerreichs)","l549fc":"Archäologischer Park Petra, UNESCO-Welterbe","1xoqay9":"Petra ist eine Stadt, die die Nabatäer in roten Sandstein gehauen haben, und die Hauptstadt ihres Reiches. Ein nabatäischer König kommt im Neuen Testament vor: Aretas IV., der von Petra aus regierte. Seine Tochter war mit Herodes Antipas verheiratet, bis Herodes sie verstieß, um Herodias zu heiraten – die Ehe, die Johannes der Täufer anprangerte und für die er enthauptet wurde (Kapitel 6, Machärus). Aretas zog später gegen Herodes in den Krieg und besiegte ihn. Nach seiner Bekehrung sagt Paulus, er sei „nach Arabien fortgegangen“, sehr wahrscheinlich ins Nabatäerreich; später ließ der Statthalter des Königs Aretas Damaskus bewachen, um Paulus festzunehmen. Petra wurde 1812 von einem Schweizer Reisenden der westlichen Welt bekannt gemacht und ist seit 1985 Weltkulturerbe.","ufzwv5":"Nach seiner Bekehrung eilte Paulus nicht nach Jerusalem zu den Aposteln; er ging zuerst nach Arabien. Gab es nach einem Wendepunkt in deinem Leben eine stille, verborgene „Arabien-Zeit“? Was tat Gott in dieser Zeit?","1qho5m6":"🏛️ Aufgabe: Geh durch den über einen Kilometer langen Siq und halte inne, wenn hinter der Biegung zum ersten Mal das Schatzhaus auftaucht. Wenn du die Kraft hast, steig die rund 800 Stufen zum Kloster auf dem Berg hinauf (auf dem Foto).","ezlv4e":"Welcher König, der von Petra aus regierte, wird im Neuen Testament erwähnt?","1c0ijrs":"König Aretas","lz5zre":"Etwa 3 Stunden südlich von Amman auf dem Desert Highway bis zum Petra-Besucherzentrum in Wadi Musa, wo man Tickets kauft (der Jordan Pass enthält 1–3 Tage Eintritt). Stempelpunkte gibt es am Besucherzentrum, am Schatzhaus im Siq und im Zentrum der alten Stadt. Das Gelände ist riesig – hin und zurück zum Kloster dauert fast einen ganzen Tag. Gute Schuhe tragen, Wasser und Hut mitnehmen und im Sommer die Mittagszeit meiden.","8fot4e":"Elath (Aqaba, der Hafen am Roten Meer)","1kgdefa":"Die Uferpromenade von Aqaba, rund um die Ruinen des antiken Ayla","slvvmz":"Elath lag im Bereich des heutigen Aqaba, Jordaniens einzigem Zugang zum Meer. Als Israel in der Wüste Edom umging, kam es an Elath und Ezjon-Geber vorbei. Später baute König Salomo Schiffe „zu Ezjon-Geber, das bei Eloth am Ufer des Schilfmeeres im Lande Edom liegt“, und fuhr mit den Seeleuten Hirams, des Königs von Tyrus, nach Ophir, um Gold zu holen. In römischer Zeit hieß der Ort Aila, ein Hafen, in dem eine römische Legion stationiert war; in frühislamischer Zeit wurde daneben eine neue Stadt gebaut, deren Mauern und Tore man noch heute am Meer sieht.","5kn2zz":"Von Gilead im Norden bis zum Roten Meer bist du durch ganz Jordanien gereist. Welche Geschichte welcher Station hat dich im Rückblick am meisten bewegt, und warum?","1gv3xlg":"🌊 Aufgabe: Geh hinunter ans Ufer und halte deine Hand ins Rote Meer. An klaren Tagen sieht man gleichzeitig die Küsten Ägyptens, Israels und Saudi-Arabiens.","1jgremw":"Was tat König Salomo bei Elath?","1fuawqh":"Er baute einen Tempel","phocdl":"Er baute Schiffe und fuhr aufs Meer","jwcmd0":"Er grub einen Brunnen","e0p71p":"Etwa 4 Stunden südlich von Amman auf dem Desert Highway oder etwa 2 Stunden südlich von Petra. Die Ruinen von Ayla liegen an der Uferpromenade im Stadtzentrum, der Besuch ist kostenlos. In der Nähe gibt es viele Restaurants und Strände, und die Kirche von Aqaba ist ganz nah.","jcak6f":"Der Berg Hor (Aarons Grab, Jabal Harun)","pzjnw":"Ein hoher Berg südwestlich von Petra, auf dem Gipfel ein kleines Heiligtum mit weißer Kuppel","10cby5o":"Als Israel sich dem verheißenen Land näherte, sagte Gott zu Mose, Aaron werde zu seinen Völkern versammelt werden, weil er und Mose bei den Wassern von Meriba Gottes Befehl widerspenstig gewesen waren. Da führte Mose Aaron und seinen Sohn Eleasar vor den Augen der ganzen Gemeinde auf den Berg Hor, zog Aaron seine Priesterkleider aus und legte sie Eleasar an, und Aaron starb dort auf dem Gipfel des Berges. Ganz Israel beweinte ihn dreißig Tage. Der jüdische Geschichtsschreiber Josephus berichtet, Aaron sei auf einem Berg bei Petra gestorben, deshalb hat die örtliche Tradition ihn immer mit diesem Jabal Harun („Aarons Berg“) gleichgesetzt; das kleine Heiligtum auf dem Gipfel stammt aus dem 14. Jahrhundert, darunter liegen die Ruinen eines byzantinischen „Aaronsklosters“. Viele Gelehrte meinen allerdings, der biblische Berg Hor habe im Negev im Süden Israels gelegen.","1h0u4bp":"Aarons Priesterkleider gingen an seinen Sohn Eleasar über; der Dienst hörte nicht auf, als ein Mensch ging. An wen wirst du eines Tages deine „Kleider“ weitergeben? Bereitest du ihn darauf vor?","1ck40a0":"⛰️ Aufgabe: Such von Petras Altstadt aus den höchsten Berg im Südwesten mit einer kleinen weißen Kuppel auf dem Gipfel. Wenn du hinaufsteigen kannst, schau vom Gipfel nach Osten über Petra und nach Westen über das Araba-Tal.","fimyrz":"Wer bekam nach Aarons Tod seine Priesterkleider?","1j7zzv7":"Josua","63nrw7":"Eleasar","1g5wszo":"Kaleb","2chon2":"Im Petra-Park (Petra-Ticket nötig). Von der Altstadt bis zum Gipfel sind es etwa 3 Stunden pro Weg, mit einem steilen Treppenstück, und der Weg ist schwer zu finden – ein einheimischer Beduinenführer wird empfohlen. Es gibt keinen Schatten, also morgens aufbrechen und viel Wasser und Proviant mitnehmen. Wer nicht hinaufsteigen will: Den Berg von der Altstadt aus zu sehen, ist auch gut.","oqjuyt":"Moses Quelle (Ain Musa)","ophlqw":"Eine Quelle am Ortseingang von Wadi Musa, überdacht von einem kleinen Gebäude mit drei Kuppeln","dwo7k7":"Das Volk hatte in der Wüste kein Wasser und haderte mit Mose. Gott sagte Mose, er solle „zu dem Felsen reden“, damit Wasser herauskomme, doch Mose erhob seine Hand und schlug den Felsen zweimal mit seinem Stab. Viel Wasser kam heraus, aber Gott sagte, Mose und Aaron hätten ihn nicht geheiligt, deshalb würden sie das Volk nicht nach Kanaan bringen. Die örtliche Tradition sagt, Mose habe hier den Felsen geschlagen, und darum heißt die ganze Stadt Wadi Musa („Tal des Mose“). Die Bibel verortet das Ereignis in Kades, das die meisten Gelehrten im Sinai oder im Negev suchen – es ist also nur eine Tradition, aber diese Quelle versorgte Petra tatsächlich über Jahrtausende mit Wasser, und die Nabatäer schlugen Kanäle, um es in die Stadt zu leiten.","134p63x":"Gott sagte Mose, er solle „reden“, doch im Zorn „schlug“ Mose den Felsen. Hast du kürzlich jemandem aus Ärger härter geantwortet, als Gott es wollte?","2cm2v4":"💧 Aufgabe: Geh in das Kuppelgebäude und schau, wo das Wasser aus dem Felsen fließt. Achte bei deinem Besuch in Petra auf die Wasserkanäle, die die Nabatäer entlang der Felswände gehauen haben.","sf8qs3":"Wie sollte Mose nach Gottes ursprünglicher Anweisung Wasser aus dem Felsen holen?","ytsm5a":"Ihn mit seinem Stab schlagen","yhooq2":"Zu dem Felsen reden","imik6i":"Sieben Tage vor ihm beten","32luip":"Am nördlichen Ortseingang von Wadi Musa, durch den man kommt, wenn man über die Königsstraße anreist, nahe dem Mussa Spring Hotel. Das kleine Gebäude ist kostenlos – ein bequemer Halt auf dem Weg nach Petra. Die Koordinaten sind ungefähr; frag in der Nähe die Leute nach „Ain Musa“.","19fgn8r":"Die Kirche von Aqaba","cj5lw7":"Ruinen einer Lehmziegelkirche im Zentrum von Aqaba","1ok45hl":"Zu Pfingsten waren unter denen, die die Jünger in ihren eigenen Sprachen von Gottes großen Taten reden hörten, auch „Araber“. Das Evangelium erreichte diese Gegend früh. 1998 legten Archäologen in Aqaba ein Lehmziegelgebäude frei, datiert auf etwa 293–303 n. Chr., mit einem erhöhten Podest und Gräbern – es gilt als eine der ältesten eigens als Kirche gebauten Kirchen der Welt. Damals verfolgte das Römische Reich die Christen noch, und doch hatten diese Gläubigen am Roten Meer schon ihre eigene Kirche gebaut. Sie stürzte beim großen Erdbeben von 363 n. Chr. ein und lag über 1.600 Jahre unter dem Sand begraben.","vvrzbd":"In einer Zeit der Verfolgung bauten diese Gläubigen trotzdem Ziegel für Ziegel einen Versammlungsort. Gibt es dort, wo du lebst, eine Gruppe von Menschen, mit denen du deinen Glauben gemeinsam „aufbauen“ kannst?","x77d57":"🧱 Aufgabe: Schau dir die Kirchenmauern genau an und finde heraus, wie die Lehmziegel einzeln aufeinandergeschichtet wurden. Stell dir diese Gläubigen vor, wie sie hier vor 1.700 Jahren sangen und beteten.","foe1wo":"Wann ungefähr wurde die Kirche von Aqaba gebaut?","mcv5e3":"1000 v. Chr.","1mqsls0":"Um 300 n. Chr.","n0h08q":"1500 n. Chr.","1br9uo4":"Im Zentrum von Aqaba, wenige Gehminuten von den Ruinen von Ayla an der Uferpromenade. Das Gelände ist eingezäunt, aber von außen gut zu sehen, und kostenlos. Gut mit Elath (den Ruinen von Ayla) zu verbinden.","jwreb7":"Ezjon-Geber (Salomos Hafen)","tl4xj8":"Lage unsicher: das Nordende des Golfs von Aqaba oder die Pharaoneninsel in Ägypten","31s2jj":"Ezjon-Geber war eines der Lager Israels in der Wüste und der Hafen, in dem König Salomo seine Schiffe baute. Später wollte König Josaphat von Juda Salomos Beispiel folgen und baute große Schiffe, um Gold aus Ophir zu holen, doch sie zerschellten bei Ezjon-Geber und fuhren nie aus. Wo Ezjon-Geber lag, ist unter Gelehrten bis heute umstritten: Manche nennen Tell el-Kheleifeh, einen kleinen Hügel an der Grenze zwischen Aqaba und Israel, andere die Pharaoneninsel vor der Küste des ägyptischen Sinai. Deshalb ist dies ein verborgenes Level.","1a314l5":"Josaphats Schiffe zerbrachen, bevor sie den Hafen verließen. Hattest du einen Plan, der scheiterte, bevor er begann? Hat Gott dich im Rückblick vielleicht dadurch bewahrt?","6nbmm0":"🔒 Verborgene Aufgabe: Lies 1. Könige 22,48–49 und 2. Chronik 20,35–37 und komm dann zum Quiz zurück.","1t62168":"Was geschah mit Josaphats Schiffen bei Ezjon-Geber?","yd01k0":"Sie brachten viel Gold zurück","vqgjx8":"Sie zerschellten und fuhren nie aus","1nmvtk5":"Piraten kaperten sie","1mmeju4":"Pella (Zuflucht der frühen Gemeinde)","19x7noe":"Die Ruinen von Tabaqat Fahl im nördlichen Jordantal","grz2b6":"Jesus hatte seine Jünger gewarnt: „Wenn ihr aber Jerusalem von Heerscharen umzingelt seht … dann sollen die in Judäa auf die Berge fliehen.“ Der Kirchengeschichtsschreiber Eusebius berichtet, dass die Gläubigen in Jerusalem, durch eine Offenbarung gewarnt, vor der Zerstörung Jerusalems durch das römische Heer im Jahr 70 n. Chr. östlich des Jordan nach Pella flohen. Pella war eine der Städte der Dekapolis; die Evangelien berichten, dass der Mann, den Jesus von Dämonen befreite, hinging, um „in der Dekapolis auszurufen, wie viel Jesus an ihm getan hatte“. Auf dem Gelände gibt es ein römisches Theater und byzantinische Kirchen; dank einer nie versiegenden Quelle am Fuß des Hügels leben hier seit der Bronzezeit Menschen.","1l0ytg8":"Die ersten Gläubigen hörten auf Jesu Worte, verließen rechtzeitig die vertraute Stadt und fingen östlich des Jordan neu an. Drängt Gott dich, einen vertrauten Ort zu verlassen, der nicht mehr sicher ist?","qowkfr":"⛲ Aufgabe: Such die Quelle am Fuß des Hügels, steig dann auf den kleinen Hügel im Osten und überblicke das ganze Jordantal. Stell dir Familien vor, die vor zweitausend Jahren aus Jerusalem flohen und diesen Ort zum ersten Mal sahen.","dst6k3":"Wohin flohen die Gläubigen aus Jerusalem laut Kirchengeschichte vor dem Jahr 70?","1xyf5nh":"Nach Pella","zvsk5b":"Nach Petra","1hvuuzl":"An der Jordantal-Straße (Route 65), etwa 40 Minuten Fahrt von Irbid oder 1,5 Stunden von Amman. Das Gelände ist für Besucher geöffnet, und am Hang gibt es ein Restaurant mit Blick über das Tal. Gut mit Gadara und Irbid aus Kapitel 1 zu verbinden. Im Sommer ist das Tal heiß, morgens ist es am besten.","1dr2nks":"Abel-Mehola (wo Elisa berufen wurde)","ot1f5z":"Der Hügel Tell Abu Sus im Jordantal","7su4ck":"Nachdem Elia am Horeb Gottes stilles, sanftes Säuseln gehört hatte, sagte Gott ihm, er solle „Elisa, den Sohn Saphats, von Abel-Mehola“ an seiner Statt zum Propheten salben. Als Elia Elisa fand, pflügte dieser mit zwölf Joch Rindern ein Feld. Elia ging an ihm vorüber und warf seinen Mantel auf ihn. Elisa kehrte um, nahm das Joch Rinder und schlachtete sie, kochte ihr Fleisch mit dem Geschirr der Rinder, gab es den Leuten zu essen, und dann machte er sich auf, folgte Elia und diente ihm. Den Pflug zu verbrennen und die Rinder zu essen hieß: Ich gehe nicht zurück. Später, am Jordan (Kapitel 4), hob Elisa den Mantel auf, der Elia entfallen war, als er hinweggenommen wurde, und begann seinen eigenen Dienst.","1dflgny":"Elisa verbrannte seinen Pflug und schnitt sich den Rückweg ab. Wenn Gott dich ruft – gibt es einen „Pflug“, den du immer noch nicht verbrennen kannst?","m0e6wl":"🐂 Aufgabe: Schau auf die Felder rund um den Hügel und versuch dir zwölf Joch Rinder vorzustellen, die zusammen pflügen. Lies 1. Könige 19,19–21.","pff0yz":"Was tat Elisa, als Elia ihn fand?","vxwb9v":"Er fischte am Fluss","16buk65":"Er pflügte mit Rindern","1dszex0":"Er opferte im Tempel","15o2r49":"⚠️ Ein archäologischer Hügel ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt. Er liegt westlich der Jordantal-Straße nahe am Fluss, etwa 15 Minuten südlich von Pella. Die Gegend ist grenznah und kann militärisches Sperrgebiet sein – nicht an Schildern oder Kontrollposten vorbeigehen; die nahe Straße liegt im Stempelradius.","2qgu8t":"Zaphon und Zarethan (Tell es-Sa'idiyeh)","lczg2":"Ein großer Hügel im mittleren Jordantal","140izov":"Die Männer von Ephraim, verärgert, weil man sie nicht zum Kampf gegen die Ammoniter gerufen hatte, versammelten sich und zogen hinüber, um den Richter Jephta zur Rede zu stellen (das hebräische Wort für „nordwärts“ kann auch als Ortsname Zaphon gelesen werden), und es kam zum Kampf. Die Gileaditer besetzten die Furten des Jordan; wenn ein Ephraimiter hinüberwollte, ließen sie ihn „Schibboleth“ sagen. Die Ephraimiter konnten es nicht richtig aussprechen und sagten „Sibboleth“ – so wurden sie erkannt und getötet. Ein einziger Akzent wurde zur Grenze zwischen Leben und Tod. Viele Gelehrte setzen Zaphon mit diesem großen Hügel gleich; andere halten ihn für Zarethan, wo König Salomo die Bronze für den Tempel „in dichter Erde zwischen Sukkoth und Zarethan“ goss (Sukkoth liegt nahebei, Kapitel 2). Archäologen fanden hier alte Mauern, einen Friedhof und eine Steintreppe, die zu einer Quelle hinabführt.","einarp":"Ein einziger Akzent teilte ein Volk in zwei Lager. Hast du jemanden schon einmal innerlich ins „andere Lager“ gesteckt, wegen seines Akzents, seiner Herkunft oder seiner Art zu reden?","o3zi5t":"🗣️ Aufgabe: Versucht mit deinen Begleitern, „Schibboleth“ und „Sibboleth“ auf verschiedene Arten zu sagen. Denk dann darüber nach: Was ist in der Kirche von heute unser „Schibboleth“ geworden?","fgh37p":"Mit welchem Wort erkannten die Gileaditer die Ephraimiter?","1ha2hr5":"Halleluja","e4wh3h":"Schibboleth","hejoxl":"Immanuel","70fiim":"⚠️ Ein archäologischer Hügel ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt. Er liegt an der Jordantal-Straße, etwa 20 Minuten nördlich von Sukkoth (Tell Deir Alla) aus Kapitel 2, sodass du beides zusammen besuchen kannst. Im Sommer sehr heiß – viel Wasser mitnehmen.","i4mp31":"Roglim (Heimat Barsillais)","g5nne9":"Rund um Zaharet, südlich von Irbid","cr5ltp":"Auf der Flucht vor seinem Sohn Absalom erreichte David erschöpft und hungrig Machanaim östlich des Jordan. Drei Männer kamen mit Betten, Schalen, Weizen, Bohnen, Honig und Käse, um ihn zu versorgen, und einer von ihnen war Barsillai, der Gileaditer, aus Roglim. Als der Krieg vorbei war und David nach Jerusalem zurückkehrte, lud er den achtzigjährigen Barsillai ein, mitzukommen und sich im Palast versorgen zu lassen. Barsillai lehnte ab: „Ich bin heute achtzig Jahre alt … Laß doch deinen Knecht zurückkehren, daß ich in meiner Stadt sterbe.“ Er empfahl den jungen Kimham an seiner Stelle. Barsillai half David an seinem Tiefpunkt und verlangte nichts zurück, als David wieder obenauf war.","16r05f5":"Barsillai war da, als jemand in Not war, und trat zurück, als dieser Mensch wieder aufstieg. Ist jemand in deinem Umfeld gerade „auf der Flucht“ und braucht von dir ein Bett oder eine Mahlzeit?","15xscop":"🍯 Aufgabe: Kauf in einem Laden vor Ort etwas Honig oder Käse (einiges von dem, was Barsillai David brachte) und teile es mit deinen Begleitern oder mit Einheimischen.","10zthjm":"Wie alt war Barsillai, als David ihn nach Jerusalem einlud?","c00rov":"Vierzig","1u7lc1o":"Sechzig","gulu8b":"Achtzig","1cwkd8y":"In den Dörfern südlich von Irbid, etwa 20 Minuten Fahrt von Irbid – gut mit Irbid und Gadara aus Kapitel 1 zu verbinden. Ein gewöhnliches Dorfgebiet ohne Ruinen oder Besuchereinrichtungen; in der Nähe des Dorfes bist du im Stempelradius. Die Lage ist eine Schätzung der Gelehrten.","1jsbanp":"Lodebar (wo Mephiboseth lebte)","1pxrbz5":"Lage unsicher, möglicherweise nahe dem Jarmuk","m7mr8o":"Als David König geworden war, fragte er: „Ist noch jemand da, der vom Hause Sauls übriggeblieben ist, daß ich Güte an ihm erweise um Jonathans willen?“ Jonathan hatte einen Sohn, Mephiboseth, an beiden Füßen lahm, der sich östlich des Jordan im Haus Makirs in Lodebar versteckt hielt – ein Name, der wohl „ohne Weide“ bedeutet, ein Ort des „Nichts“. Damals löschte ein neuer König das alte Königshaus aus; deshalb fiel Mephiboseth vor David auf sein Angesicht: „Was ist dein Knecht, daß du dich zu einem toten Hunde gewendet hast, wie ich einer bin?“ Doch David gab ihm alles Land Sauls zurück und ließ ihn „beständig an seinem Tische essen wie einer der Königssöhne“. Später, als David nach Machanaim floh, war einer von denen, die ihm Vorräte brachten, Makir aus Lodebar. Die genaue Lage Lodebars ist bis heute unsicher, deshalb ist dies ein verborgenes Level.","1p6cdd0":"Mephiboseth wurde von einem Ort des „Nichts“ an den Tisch des Königs geholt. Siehst du dich vor Gott als „toten Hund“ oder als Kind des Königs?","3krxdd":"🔒 Verborgene Aufgabe: Lies 2. Samuel 9 und komm dann zum Quiz zurück.","658bkn":"Um wessentwillen erwies David Mephiboseth Güte?","a112xk":"Saul","llu04c":"Jonathan","vrn6mq":"Samuel","1gelkw2":"Die Königsstraße","3lx3k2":"Route 35 von Madaba nach Süden bis Edom; jeder Abschnitt zählt","1qb3940":"Als Israel sich dem verheißenen Land näherte, sandte Mose zweimal Boten, um Durchzug zu erbitten – zuerst zum König von Edom, dann zu Sihon, dem König der Amoriter –, mit denselben Worten: „Auf der Straße des Königs wollen wir ziehen, wir wollen nicht ausbiegen zur Rechten noch zur Linken, bis wir durch dein Gebiet gezogen sind.“ Beide Male wurde es abgelehnt. Diese „Straße des Königs“ ist die heutige Königsstraße, eine der ältesten ununterbrochen genutzten Straßen der Welt: Antike Karawanen, nabatäische Kamelzüge mit Weihrauch, die „Via Nova Traiana“ des römischen Kaisers Trajan und byzantinische Pilger zogen alle hier entlang. Die Kapitel 5 bis 8 dieser Reise liegen fast ganz an ihr.","s4rd70":"Israel bat höflich und wurde trotzdem abgewiesen. Wie reagierst du gewöhnlich, wenn man dir eine Absage erteilt – mit Gewalt durchsetzen, nachtragend sein, oder wie Israel den langen Umweg nehmen?","1l8vcep":"🛣️ Aufgabe: Such dir bei der Fahrt auf der Königsstraße ein ruhiges gerades Stück, mach die Musik aus und sei fünf Minuten still. Denk daran, wie viele Menschen in dreitausend Jahren auf dieser Straße ihren Weg gesucht haben.","1r3caqc":"Wie versprach Mose zu reisen, als er um Durchzug bat?","190ala8":"Nur auf der Königsstraße, ohne nach rechts oder links abzubiegen","1bbw8v1":"Nachts heimlich hindurchschleichen","tqx73g":"In zwölf Gruppen aufgeteilt","s120tk":"Kein bestimmter Punkt nötig: Madaba, Dhiban, Kerak, Tafila und Busayra liegen alle an der Königsstraße, und wer durch einen dieser Orte fährt, ist im Stempelradius. Die Straße ist hügelig und kurvig – viel langsamer als der Desert Highway, aber viel schöner; von Madaba nach Petra ist ein guter ganzer Tag.","aq2hjg":"Jaser (das Weideland, das Ruben und Gad wählten)","e05odi":"Die Ruinen von Khirbet Sara westlich von Amman","1msx9r4":"Nachdem Israel Sihon besiegt hatte, sahen die Stämme Ruben und Gad, dass das Land Jaser und Gilead ideal für Vieh war – und sie hatten sehr viel Vieh –, und so kamen sie zu Mose: „Laß uns nicht über den Jordan ziehen.“ Mose wurde zornig: „Sollen eure Brüder in den Streit ziehen, und ihr wollt hier bleiben?“ Er erinnerte sich, wie vierzig Jahre zuvor der böse Bericht der Kundschafter das ganze Volk davon abgehalten hatte, nach Kanaan hineinzuziehen. Schließlich willigten die beiden Stämme ein: Sie ließen Familien und Herden östlich des Jordan zurück, während die Männer bewaffnet hinüberzogen, um an der Seite ihrer Brüder zu kämpfen, und erst heimkehrten, als ganz Israel sein Erbteil erhalten hatte. Und sie hielten Wort (Josua 22).","wax4q1":"Ruben und Gad sahen zuerst das Land, das für sie selbst am besten war; Mose erinnerte sie daran, die Not ihrer Brüder zu sehen. Hat eine deiner letzten Entscheidungen die Menschen um dich herum berücksichtigt?","vkdbqd":"🐑 Aufgabe: Such die Hänge um dich herum nach Schafherden ab. Stell dir die Hirten von Ruben und Gad vor, wie sie hier stehen und denken: „Das ist der Ort.“","wmatcm":"Warum wollten Ruben und Gad östlich des Jordan bleiben?","kbiuu8":"Sie fürchteten die Schlacht","59oa3g":"Sie hatten viel Vieh, und dies war gutes Weideland","mmaq8d":"Mose sagte ihnen, sie sollten bleiben","1n3tgdv":"⚠️ Eine Ausgrabungsstätte ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt. Sie liegt westlich von Amman Richtung Wadi es-Sir, etwa 30 Minuten Fahrt vom Zentrum Ammans. Dies ist einer von mehreren Vorschlägen der Gelehrten; die genaue Lage Jasers ist noch umstritten.","1384td7":"Bezer (eine Zufluchtsstadt)","6m1yof":"Die Ruinen von Umm el-Amad nordöstlich von Madaba","6l2ln6":"Östlich des Jordan sonderte Mose drei „Zufluchtsstädte“ aus: Bezer in der Wüste auf der Hochebene, Ramot in Gilead (Kapitel 1) und Golan in Basan. Wer jemanden versehentlich, ohne Hass, getötet hatte, konnte in eine dieser Städte fliehen und war dort sicher vor der Rache der Familie des Opfers, bis die Gemeinde gerecht richten konnte. Die drei Städte waren über Süden, Mitte und Norden des Landes verteilt, damit die Menschen überall eine in Reichweite hatten. Auch die Mescha-Stele (Kapitel 6) erwähnt Bezer: Mesa sagt, er habe es wieder aufgebaut.","z6i6my":"Mitten im Gesetz schuf Gott einen Ausweg für Menschen, die einen schrecklichen Fehler gemacht hatten. Gibt es in deiner Nähe jemanden, der versagt hat und einen sicheren Ort braucht? Könntest du seine „Zufluchtsstadt“ sein?","hbzxq9":"🛡️ Aufgabe: Such dir einen hohen Punkt in den Ruinen und schau dich um. Stell dir einen verängstigten Mann vor, der den ganzen Weg hierher rennt, und seine Erleichterung, als er das Stadttor sieht.","1oqczkb":"Für wen waren die Zufluchtsstädte gedacht?","pskkdz":"Für Deserteure","bo55ga":"Für alle, die jemanden versehentlich, ohne Hass, getötet hatten","6l9gga":"Für Menschen mit Schulden","wvnkq3":"⚠️ Eine Ausgrabungsstätte ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt. Sie liegt in der Ebene nordöstlich von Madaba und südlich von Amman, etwa 25 Minuten Fahrt von Madaba. Dies ist einer von mehreren Vorschlägen der Gelehrten.","bt6zwx":"Beth-Jesimot (das letzte Lager vor dem Übergang)","2vtgvc":"Der Hügel Tell Azeimeh nördlich des Toten Meeres","178wc5a":"4. Mose 33 verzeichnet jede Station auf Israels Weg aus Ägypten, und die letzte lautet: „Sie lagerten am Jordan, von Beth-Jesimot bis Abel-Sittim in den Ebenen Moabs.“ Vierzig Jahre und mehr als vierzig Lager gingen hier zu Ende. Der nächste Schritt war der Zug über den Jordan (Kapitel 4). Beth-Jesimot war das Südende dieses großen Lagers, Sittim das Nordende.","4up4z6":"Das 4. Buch Mose verzeichnet jedes einzelne Lager, auch die, die unscheinbar wirken. Wenn du auf dein Leben zurückschaust: Welche „unscheinbare“ Zeit war in Wahrheit Gottes Führung?","1w8on5v":"📜 Aufgabe: Lies 4. Mose 33 und zähl, wie viele Stationen Israel hatte. Schau dann nach Westen – der Jordan ist nicht weit.","ce71dz":"Das wievielte Lager war Beth-Jesimot, bevor Israel den Jordan überquerte?","1ao7gfb":"Das erste Lager","13gc7c1":"Das letzte Lager","1kfjo2r":"Das Lager am Berg Sinai","9jx2xi":"⚠️ Ein archäologischer Hügel ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt. Er liegt nördlich des Toten Meeres nahe der Straße zum Hotelgebiet – gut mit der Taufstelle, Sittim und den Ebenen Moabs aus Kapitel 4 zu verbinden. Im Sommer sehr heiß; die Mittagszeit meiden.","2we3kt":"Unsere Liebe Frau vom Berge, Anjara","1isf2bp":"Die Stadt Anjara in den Bergen von Ajloun; eine Höhle neben der Kirche","bb36zm":"Die örtliche katholische Tradition sagt, dass Jesus, seine Mutter Maria und die Jünger auf dem Weg von Galiläa durch die Dekapolis nach Jerusalem in einer Höhle in Anjara rasteten. Die Bibel berichtet das nicht, es ist also eine Tradition; aber die Evangelien erzählen sehr wohl, dass Jesus durch die Dekapolis zog und seine Jünger oft von der Menge wegführte, damit sie ausruhten: „Kommt ihr selbst her an einen öden Ort und ruht ein wenig aus.“ Heute steht neben der Höhle die Kirche Unserer Lieben Frau vom Berge; im Jahr 2000 erklärte der Vatikan sie zu einer von fünf Pilgerstätten in Jordanien, und jedes Jahr im Juni kommen über tausend Pilger.","1irhtn":"Jesus nahm seine Jünger bewusst zur Seite, damit sie ausruhten. Hast du auf dieser Reise Zeit gelassen, um „ein wenig auszuruhen“, oder eilst du immer schon zur nächsten Station?","7y8fp0":"🕯️ Aufgabe: Setz dich fünf Minuten still in die Höhle und tu nichts, als auszuruhen. Achte sonntags auf die Gottesdienstzeiten und nimm Rücksicht auf die, die hier beten.","1o5nde8":"Jesus sagte zu seinen Jüngern: „Kommt ihr selbst her an einen öden Ort und …“ was?","10ysh5b":"Fastet","jxp7w1":"Ruht ein wenig aus","1o37kmm":"Predigt","19wehh7":"In der Stadt Anjara bei Ajloun, etwa 25 Minuten Fahrt von Jerash – gut mit Gerasa und Elias Heimatort Tisbe aus Kapitel 1 zu verbinden. Die Kirche ist für Besucher geöffnet; bitte angemessen kleiden. Die Koordinaten sind ungefähr die Stadtmitte – frag im Ort nach „Sayidat al-Jabal“.","1tjqvtb":"Das Land Uz (Hiobs Heimat)","1onw7p2":"Lage unsicher, möglicherweise in Edom","g7lxve":"Das Buch Hiob beginnt: „Es war ein Mann im Lande Uz, sein Name war Hiob.“ Er war vollkommen und rechtschaffen und gottesfürchtig, und doch verlor er an einem einzigen Tag alle seine Herden und Knechte, und sogar seine zehn Kinder starben. Hiob zerriss sein Gewand, fiel zur Erde und betete an: „Jehova hat gegeben, und Jehova hat genommen, der Name Jehovas sei gepriesen!“ Niemand weiß genau, wo Uz lag; die Klagelieder bringen es mit Edom in Verbindung („Tochter Edom, die du im Lande Uz wohnst“), und auch Hiobs Freund Eliphas war ein Temaniter aus Edom (Kapitel 8). Deshalb ist dies ein verborgenes Level.","mbdjal":"In seinem größten Verlust entschied sich Hiob trotzdem anzubeten. Wenn du etwas verlierst, was ist deine erste Reaktion?","6qmx50":"🔒 Verborgene Aufgabe: Lies Hiob Kapitel 1, 2 und 42 und komm dann zum Quiz zurück.","1iqhwxg":"Was sagte Hiob, nachdem er alles verloren hatte?","1iq4e42":"„Warum hat Gott mich verlassen?“","k082o":"„Jehova hat gegeben, und Jehova hat genommen“","ru9tsp":"„Ich verlasse das Land Uz“","3e0isv":"Das Gebirge Seir (Esaus Bergland)","1bqa5q0":"Die edomitischen Berge rund um Petra (heute das Sharah-Gebirge)","1jekp6g":"Auf seinem Heimweg (Kapitel 2) fürchtete Jakob am meisten seinen Bruder Esau in Seir. Doch Esau lief ihm entgegen, umarmte ihn, küsste ihn, und beide weinten. Nach ihrer Versöhnung „kehrte Esau an jenem Tage auf seinem Wege nach Seir zurück“. Jahrhunderte später, als Israel hier vorbeizog, gab Gott einen klaren Befehl: Kämpft nicht gegen Esaus Nachkommen, „denn das Gebirge Seir habe ich dem Esau als Besitztum gegeben“. Das Gebirge Seir ist die Kette roter Berge rund um Petra, heute Sharah-Gebirge genannt.","fufojg":"Nach ihrer Versöhnung gingen Jakob und Esau getrennte Wege, aber nicht mehr als Feinde. Versöhnung heißt nicht immer, jeden Tag zusammen zu sein. Welche deiner Beziehungen braucht diesen Frieden des „versöhnt, aber jeder lebt sein Leben“?","eybhbq":"⛰️ Aufgabe: Such dir einen hohen Punkt in Petra oder Wadi Musa und schau auf die roten Berge ringsum. Denk an jemanden, von dem du dich entfernt hast, und bete für ihn.","1xc8jxb":"Wohin kehrte Esau nach der Versöhnung mit Jakob zurück?","1rz18jm":"Nach Seir","1rakwcr":"Dies ist eine ganze Region: Wer in der Gegend von Petra und Wadi Musa ist, ist im Stempelradius – keine eigene Fahrt nötig.","95viy6":"Das Tote Meer (das Salzmeer)","u35bx8":"Öffentliche Strände und Resorts am Ostufer des Toten Meeres","ioolqj":"Die Bibel nennt es das „Salzmeer“; das 1. Buch Mose sagt, das Tal Siddim, wo zur Zeit Abrahams Könige kämpften, „ist das Salzmeer“. Es ist der tiefste Punkt der Landoberfläche der Erde und so salzig, dass kein Fisch darin leben kann. Doch der Prophet Hesekiel sah eine Vision: lebendiges Wasser, das aus dem Tempel nach Osten ins Salzmeer floss, „und die Wasser werden gesund werden“ – „alles wird leben, wohin der Fluss kommt“, und Fischer werden sogar am Ufer ihre Netze ausbreiten. Der Ort, an dem Leben am unwahrscheinlichsten ist, wird in Gottes Verheißung zum Ort voller Leben.","otgp9k":"Hesekiel sah sogar das toteste Meer lebendig werden. Gibt es in deinem Leben ein „totes Meer“, von dem du denkst, dort werde nie wieder etwas leben?","1697to8":"🌊 Aufgabe: Lass dich auf dem Toten Meer treiben und schau in den Himmel. Lies danach am Ufer Hesekiel 47,1–12. (Vorsicht: Das Wasser brennt stark in den Augen – nicht spritzen und nicht untertauchen.)","1cewyde":"Was geschah in Hesekiels Vision, als das lebendige Wasser das Salzmeer erreichte?","1mfrn3m":"Das Wasser wurde noch salziger","wf4elz":"Das Wasser wurde gesund, und alles lebte","1q8kn2k":"Das Meer trocknete aus","14kdnd7":"Etwa 1 Stunde Fahrt von Amman. Am Nordufer gibt es einen kostenpflichtigen öffentlichen Strand (Amman Tourist Beach) mit Duschen, und Resorthotels verkaufen Tagespässe. Ein bis zwei Tage vorher nicht rasieren (Salzwasser brennt stark in kleinen Schnitten); viel trinken, und mittags ist es im Sommer extrem heiß. Gut mit der Taufstelle aus Kapitel 4 zu verbinden.","1qszqmw":"Adam (wo der Jordan stehen blieb)","14okslk":"Der Hügel Tell ed-Damiyeh nahe der Damia-Brücke","1oie0v4":"Als Israel den Jordan überqueren wollte, war Erntezeit, und der Fluss trat über alle seine Ufer. Sobald die Priester, die die Lade trugen, ins Wasser traten, „stand das von oben herabfließende Wasser; es richtete sich auf wie ein Damm, sehr fern, bei der Stadt Adam, die seitwärts von Zarethan liegt“, und das Volk zog trocken gegenüber von Jericho hinüber. Die meisten Gelehrten setzen Adam mit diesem Hügel, Tell ed-Damiyeh, gleich, etwa 30 km flussaufwärts von der Taufstelle. Die Geschichte verzeichnet, dass bei den Erdbeben von 1267 und 1927 hier in der Nähe Uferhänge einstürzten und den Jordan stundenlang aufstauten. Ob Gott etwas Ähnliches benutzte, sagt die Bibel nicht; aber der Zeitpunkt kam genau, als die Priester ins Wasser traten.","u70n16":"Das Wasser blieb stehen, nachdem die Priester hineingetreten waren, nicht vorher. Wartet Gott darauf, dass du den ersten Schritt tust?","uqdv5k":"🦶 Aufgabe: Lies Josua 3 und stell dir vor, wie sich die Priester in dem Moment fühlten, als ihre Füße das reißende Wasser berührten.","1k7u22c":"Wann blieb das Wasser des Jordan stehen?","92ifl9":"Nachdem Israel sieben Tage gebetet hatte","ai2ovb":"Als die Füße der Priester das Wasser berührten","111gbd6":"Als Mose seinen Stab erhob","164ur9n":"⚠️ Ein archäologischer Hügel ohne Besuchereinrichtungen; der Zugang ist nicht bestätigt. Er liegt an der Jordantal-Straße nahe der Mündung des Jabbok in den Jordan, etwa 15 Minuten von Sukkoth (Kapitel 2). Er liegt nahe einem Grenzübergang und kann Sperrgebiet sein – nicht mit Gewalt hineingehen; die nahe Straße liegt im Stempelradius.","1hz6236":"Bileams Segen (Feld Zophim, Gipfel des Pisga)","gxpac0":"Der Höhenzug beim Berg Nebo","wuvmvu":"Balak, der König von Moab, sah Israel in den Ebenen lagern und erschrak, deshalb bezahlte er den Propheten Bileam, um es zu verfluchen. Balak führte Bileam zuerst auf „die Höhen des Baal“, dann „auf das Feld der Wächter, auf den Gipfel des Pisga“ und schließlich auf den Gipfel des Peor (Kapitel 5) und baute jedes Mal sieben Altäre. Doch jedes Mal, wenn Bileam den Mund öffnete, kamen nur Segensworte heraus. Im letzten sah er weit in die Zukunft: „Es tritt hervor ein Stern aus Jakob, und ein Zepter erhebt sich aus Israel.“ Viele Christen lesen diesen Stern als Weissagung auf den Messias. 1967 fanden Archäologen in Sukkoth (Deir Alla, Kapitel 2) einen alten Text, der „Bileam, Sohn Beors“ nennt – ein Zeugnis über Bileam außerhalb der Bibel.","2ivwgc":"Balak wechselte dreimal den Ort, in der Hoffnung, ein anderer Blickwinkel würde den Fluch wirksam machen, und jedes Mal wurde daraus ein Segen. Benutzt jemand deine Vergangenheit, um dich zu „verfluchen“? Was sagt Gott über dich?","3ig4o9":"🔭 Aufgabe: Schau vom Höhenzug hinunter auf die Ebenen Moabs, wo Israel lagerte. Lies 4. Mose 24,5 und sprich einen Segen über den Ort, an dem du bist.","o86ohs":"Balak heuerte Bileam an, um Israel zu verfluchen. Was tat Bileam?","jihbg":"Er verfluchte Israel","zaedz1":"Er segnete Israel immer wieder","1kmr9ot":"Er weigerte sich zu reden","4w765e":"Auf dem Höhenzug beim Berg Nebo – gut mit dem Berg Nebo und Peor aus Kapitel 5 zu verbinden. Der andere Stempelpunkt liegt an der Straße vom Nebo Richtung Madaba. Die Lage ist eine Schätzung der Gelehrten; überall rund um den Berg Nebo bist du in der Nähe.","j9fdy4":"Beer (das Brunnenlied)","13gwhv5":"Lage unsicher, auf dem Weg vom Arnon nach Norden zum Pisga","1rh8o6o":"Nachdem Israel den Arnon überquert hatte, kam es nach Beer, das heißt „Brunnen“. Gott sagte zu Mose: „Versammle das Volk, und ich will ihnen Wasser geben.“ Diesmal beklagte sich niemand; alle gruben gemeinsam, sogar die Fürsten und Edlen mit ihren Zeptern und Stäben. Als das Wasser hervorsprudelte, sang Israel: „Herauf, Brunnen! Singet ihm zu!“ In vierzig Jahren Wüste ist das fast das einzige Mal, dass das ganze Volk über Wasser sang, statt zu murren. Die genaue Lage Beers ist unbekannt, deshalb ist dies ein verborgenes Level.","1gqe4ou":"Derselbe Wassermangel hatte früher Klagen ausgelöst; diesmal führte er zu gemeinsamem Graben und Singen. Könntest du dem, was dir gerade fehlt, mit einer anderen Haltung begegnen?","1k94pta":"🔒 Verborgene Aufgabe: Lies 4. Mose 21,10–20 und komm dann zum Quiz zurück.","1jaribb":"Was tat Israel in Beer?","1r1hhwb":"Es beklagte sich","4v1lwb":"Es sang dem Brunnen zu, als das Wasser hervorsprudelte","1b0s1kl":"Es führte eine Schlacht","qlg446":"Naaman wäscht sich im Jordan","bt3mcs":"Irgendwo am Jordan; die Bibel sagt nicht, wo","biflve":"Naaman, der Heerführer von Aram (Syrien), war ein tapferer Krieger, aber er war aussätzig. Ein junges israelitisches Mädchen, das als Gefangene in sein Haus gekommen war, sagte, ein Prophet in Israel könne ihn heilen. Der Prophet Elisa kam nicht einmal heraus; er ließ ihm nur sagen: „Geh hin und bade dich siebenmal im Jordan.“ Naaman wurde zornig: „Sind nicht die Flüsse von Damaskus besser als alle Wasser Israels?“ Seine Knechte redeten ihm zu: Hätte der Prophet etwas Großes von dir verlangt, hättest du es nicht getan? Wie viel mehr, wenn er nur sagt: Bade dich. Schließlich stieg Naaman hinab und tauchte siebenmal unter, „und sein Fleisch wurde wieder wie das Fleisch eines jungen Knaben“. Später, in Nazareth, nannte Jesus Naaman als Beispiel dafür, dass Gottes Gnade auch Außenstehende erreicht. Die Bibel sagt nicht, an welcher Stelle des Jordan er sich wusch, deshalb ist dies ein verborgenes Level.","1rv1y8f":"Naaman hätte seine Heilung fast verpasst, weil sie ihm zu einfach und nicht würdevoll genug erschien. Gibt es etwas Kleines, um das Gott dich bittet und das du als zu einfach abtust?","ge2aj2":"🔒 Verborgene Aufgabe: Lies 2. Könige 5 und komm dann zum Quiz zurück. (Wenn du an der Taufstelle aus Kapitel 4 bist, ist das ein wunderbarer Ort zum Lesen.)","hil00d":"Wie oft sollte sich Naaman nach Elisas Worten im Jordan waschen?","cu3hb7":"Dreimal","nb7v3m":"Reisender","u4m99m":"Suchender","13r9k0d":"Pilger","18ptlks":"Wächter","1vxtrxy":"Zeuge jenseits des Jordan","16ub04g":"3 Tage: Das Beste im Süden","19r2col":"Für Eilige: der Jordan, der Berg Nebo, die Königsstraße und Petra. Du deckst sechs Kapitel der Hauptroute ab, aber nicht den Norden oder Aqaba, also noch nicht das Zertifikat.","x49aum":"Vormittags die Zitadelle von Amman und das Römische Theater, zum Frühstück Fūl in der Innenstadt. Eine Stunde Fahrt zur Taufstelle für die Mittagszeit, dann der Berg Nebo zum Sonnenuntergang; Übernachtung in Madaba.","19whdft":"Madaba","1xw214u":"Den ganzen Tag auf der Königsstraße nach Süden – allein die Fahrt dauert 5 bis 6 Stunden, also vor 7 Uhr losfahren. Mittagessen mit Mansaf in Kerak; am Abend Ankunft in Wadi Musa.","15mrz37":"Wadi Musa (Petra)","1vah67a":"Zuerst an Moses Quelle halten, dann den ganzen Tag in Petra verbringen. Wenn du die Kraft hast, steig zum Kloster hinauf.","1h5wmah":"Wadi Musa, oder 2 Stunden Fahrt nach Aqaba","1ad05ji":"5 Tage: Gerade genug für das Zertifikat","8mkwg6":"Besuche alle 17 Pflichtstationen der neun Hauptkapitel und hol dir am Abend des 5. Tages dein Zertifikat am Roten Meer. Jeder Tag ist voll; wenn du es ruhiger magst, häng eine Nacht in Petra an.","tr2f01":"Amman → Jerash (50 Min.) → Mar Elias bei Ajloun (40 Min.) → Umm Qais (1 Std.) zum Sonnenuntergang über dem See Genezareth in Gadara.","dlbecb":"Irbid oder Umm Qais","139z6bm":"Hinunter ins Jordantal: Pella → nach Süden bis Sukkoth → König-Talal-Damm (der Jabbok) → am späten Nachmittag zurück zur Zitadelle von Amman.","1791b0d":"Amman","p2agb6":"Vormittags die Taufstelle, mittags im Toten Meer treiben, nachmittags der Berg Nebo, Übernachtung in Madaba.","b8cjtf":"Ein ganzer Tag nach Süden auf der Königsstraße; vor 7 Uhr losfahren. Mittagessen in Kerak, abends in Wadi Musa.","15n45ih":"Früh nach Petra, mindestens einen halben Tag; nachmittags 2 Stunden nach Aqaba fahren, in der Dämmerung die Hand ins Rote Meer halten und im Tab „Pass“ dein Zertifikat holen.","17ffqqr":"Aqaba","17b1c1x":"7 Tage: Gemütliches Tempo, mit Nebenrouten","117n9nx":"Alle 17 Pflichtstationen der Hauptroute (du bekommst also das Zertifikat), mit Zeit an jedem Tag zum Lesen und Nachdenken, plus Stationen der Nebenrouten unterwegs. Unsere Top-Empfehlung.","1y6xyua":"Ein entspannter erster Tag in Amman: Zitadelle und Römisches Theater, Fūl in der Innenstadt. Lies heute Abend die verborgenen Level in der App – so kannst du schon vor der Abreise mehrere Stempel sammeln.","3bk4qz":"Das nördliche Bergland: Jerash → Anjara → Elias Heimatort → Umm Qais zum Sonnenuntergang. Von Oktober bis Dezember unterwegs an einer Ölmühle halten.","m6wchb":"Durchs Jordantal nach Süden: Elisa, Schibboleth und Adam, wo der Fluss stehen blieb, bis zum Jabbok. Zur Übernachtung hinunter ans Tote Meer.","exl1cc":"Nördliches Totes Meer","9p6j78":"Vormittags die Taufstelle, mittags im Toten Meer treiben und Hesekiel 47 lesen, nachmittags der Berg Nebo und Bileams Höhenzug; Übernachtung in Madaba.","s4kcwn":"Die nördliche Königsstraße: die Mosaike von Mephaat, die Festung Johannes des Täufers, die Arnon-Schlucht, dann über Ruths Hochebene Moab nach Kerak. Zum Abendessen Mansaf.","1emrowd":"Kerak","17otwsl":"Über den Sered nach Edom: Tafila und Bozra (Linsensuppe in Esaus Heimat), abends Ankunft an Moses Quelle und in Wadi Musa.","193mxio":"Vormittags Petra, dann 2 Stunden nach Aqaba zur alten Kirche und zum Roten Meer. Hol dir am Ufer dein Zertifikat und blicke auf die sieben Tage zurück.","kmscd9":"Bibelpfad Jordanien","j1sac1":"Karte","1xlzdhv":"Kapitel","or79qb":"Pass","onrqou":"Info","zvhet":"📍 Wo bin ich?","17r0qjw":"Die Karte braucht Internet. Offline nutzt du den Tab „Kapitel“ – Stempel und Bibelstellen funktionieren weiterhin.","3q2rad":"Titel: ","lvjjoy":"Kapitel {n}","1wdce2q":"Pflicht","wkfe1w":"Bonus","n6hn1l":"Öffnen","1jgmzoq":"← Zurück","1tmo59u":"Abgeschlossen","173ld1z":"Goldabzeichen!","1o9xolf":"Besuche die Pflichtstationen, um abzuschließen","3b783r":"Stempel {a} / {b}","shfa13":"Quizsterne {a} / {b}","11achfl":"📖 Bibelstelle","1wzvnle":"📜 Die Geschichte","8fvktu":"💭 Zum Nachdenken","1fnheed":"🎯 Aufgabe vor Ort","1aepw8z":"❓ Quiz","squysj":"🚗 Anreise","7yv3pi":"🛂 Stempel holen","1o1eym1":"Wenn du vor Ort bist, tipp auf den Knopf. Dein Handy prüft deinen Standort und stempelt deinen Pass, wenn du im Umkreis bist. Dein Standort wird nur auf deinem Handy verglichen und nirgendwohin gesendet.","1dm73lp":"📍 Ich bin hier – stempeln!","1shxlgx":"Standort wird geprüft … (bis zu 20 Sekunden)","kbmfth":"Gestempelt","195urn3":"Gestempelt am {d}","x5lcoe":" (manuell)","5dr94h":"Du bist etwa {km} km entfernt. Versuch es noch einmal, wenn du angekommen bist!","gi8ctb":"Der Standortzugriff wurde verweigert. Erlaube in den Handy-Einstellungen den Standort für deinen Browser und versuch es erneut.","1rs8b0r":"Standort konnte nicht ermittelt werden (vielleicht drinnen oder schwaches Signal).","1qkk4dz":"Dieser Browser unterstützt keine Standortbestimmung.","3h2fa1":"GPS ungenau, aber du bist sicher, dass du vor Ort bist? Du kannst manuell stempeln (im Pass als „manuell“ markiert).","11xqiho":"Ich bin vor Ort – manuell stempeln","gf0jzd":"Bist du sicher? Tipp auf „Bestätigen“, um zu stempeln.","18tbqwf":"Bestätigen","ew9em3":"Abbrechen","bah4r7":"Richtig! ⭐ Du hast einen Stern verdient","1qnmrdf":"Nicht ganz – die Antwort steht in der Bibelstelle!","1my26yu":"⭐ Beantwortet","19wz7gh":"Foto: ","9e1qku":"⚠️ Keine Besuchereinrichtungen","ig9zld":"📍 Ungefähre Lage (noch zu prüfen)","jeqmcc":"✅ Weitgehend anerkannte Lage","wqpwcl":"🤔 Wahrscheinliche Lage","z018wo":"🕯️ Traditionsort (seit Jahrhunderten von Gläubigen verehrt)","17889nd":"🗺️ Eine ganze Region","foydn6":"❓ Lage unsicher","gp48rd":"Verborgen","1qwt13w":"🔒 Dies ist ein verborgenes Level: Die Lage ist unsicher, du musst also nicht hinfahren. Lies die Bibelstelle und die Geschichte und beantworte dann das Quiz unten, um den Stempel freizuschalten.","1x0tqhl":"🎉 {c} abgeschlossen! Abzeichen erhalten {b}","1pnerog":"🏆 {c} vollständig abgeschlossen! Dein Abzeichen ist jetzt golden","14g90ny":"🎖️ Neuer Titel: {r}","s4qz3j":"🛂 Gestempelt: {s}","1tv1wsp":"Meine Stempel","1pbueu2":"Kapitelabzeichen","xjnbje":"Fortschritt sichern","sbhrgy":"Der Fortschritt wird nur im Browser dieses Handys gespeichert. Bevor du das Handy wechselst oder Browserdaten löschst, exportiere eine Sicherungsdatei; importiere sie später, um weiterzumachen.","1geya1n":"Sicherung exportieren","15y32v6":"Sicherung importieren","1dtbsn4":"Fortschritt importiert: {n} Stempel","15q0lwm":"Diese Datei sieht nicht wie eine Bibelpfad-Sicherung aus, deshalb wurde nichts importiert.","3laxm6":"⚠️ Dieser Browser kann keine Daten speichern (vielleicht im privaten Modus); der Fortschritt geht beim Schließen verloren.","rk6wxk":"Willkommen beim Bibelpfad Jordanien!","sydf6n":"Die Hauptroute hat {c} Kapitel und {n} Orte, vom Bergland Gilead im Norden bis zum Roten Meer.\n• Lies Bibelstellen und Geschichten jederzeit – ideal zur Vorbereitung vor der Reise.\n• Tipp vor Ort auf „Ich bin hier – stempeln!“, und das GPS deines Handys bestätigt deinen Standort.\n• „Verborgene“ Level haben eine unsichere Lage – kein Besuch nötig; beantworte das Quiz, um sie freizuschalten.\n• Besuche die Pflichtstationen eines Kapitels, um es abzuschließen; besuche alle, um ein Goldabzeichen zu bekommen.\n• Nebenrouten sind freiwillige Zusatzstrecken und haben keinen Einfluss auf dein Zertifikat.\n• Schließe die Pflichtstationen aller neun Kapitel ab, um im Tab „Pass“ dein Zertifikat zu holen.\n• Die Karte braucht Internet; alles andere funktioniert offline.","jowj2w":"Verstanden, los geht's!","9h4td":"Suche deinen Standort …","q75l84":"Du bist hier","rjpku3":"🧭 Mit Google Maps navigieren","1f3vks2":"Dies ist eine ungefähre Lage – achte beim Näherkommen auf Schilder vor Ort oder frag nach dem Weg.","mkz7vi":"Nebenroute","1rqk4p":"🍽️ Biblischer Tisch","1u4zjvk":"✍️ Meine Antwort (nur auf diesem Handy gespeichert)","1b4a24y":"Ein, zwei Sätze genügen …","1ciko85":"✓ Gespeichert","16dkvce":"📓 Mein Reisetagebuch","nn4shs":"Orte mit Antwort: {n}","1c6l7vj":"Noch nichts. Öffne einen beliebigen Ort und schreib deine Antwort unter „Zum Nachdenken“.","1bmumpk":"⬇️ Tagebuch herunterladen (Textdatei)","13861xp":"Bibelpfad Jordanien · Mein Reisetagebuch","etpkgz":"🏠 Sammle {n} Stempel, bevor du überhaupt aufbrichst","ymamlb":"Diese {n} verborgenen Level haben eine unsichere Lage, du musst also nicht hinfahren: Lies die Geschichte und beantworte das Quiz, um jedes freizuschalten. Lies sie vor der Reise zu Hause, dann hast du schon Fortschritt, bevor es losgeht.","wdxza6":"Freigeschaltet {a} / {b}","oh2xig":"🗓️ Fertige Reisepläne","1vevakg":"Für Selbstfahrer: einfach folgen; tipp auf einen Ort für seine Geschichte und die Anfahrt. Häkchen zeigen Stempel, die du schon hast.","a3uppl":"Tag {n}","v7x3tx":"🛏️ Übernachtung: ","1cmrpbl":"Nebenrouten sind freiwillige Zusatzstrecken; sie haben keinen Einfluss auf dein Zertifikat.","8g179s":"🏅 Abschlusszertifikat","1623qqx":"Stempel alle Pflichtstationen der neun Kapitel, um dein Zertifikat zu erhalten; stempel alle {n} Orte, dann wird es zur Goldausgabe.","1d0csub":"Noch {a} Pflichtstationen ({b} / {c} Kapitel abgeschlossen)","nn63sw":"🎉 Herzlichen Glückwunsch! Du hast alle neun Kapitel abgeschlossen – dein Zertifikat ist bereit.","1nrci36":"🏆 Du hast jeden Ort gestempelt! Dies ist die Goldausgabe.","kt3s13":"Name auf dem Zertifikat","36gr9y":"z. B. Benson and Esther","ji7dwm":"Zertifikat erstellen","1x98p8c":"⬇️ Bild herunterladen","1orjthj":"📤 Teilen","rqyph1":"Das Zertifikat wird auf deinem Handy erstellt; dein Name wird nirgendwohin gesendet. Für eine andere Sprache stell oben rechts die Sprache um und tipp erneut auf „Zertifikat erstellen“.","yyoz1p":"Abschlusszertifikat","1y4ba45":"Goldausgabe","esj03a":"Hiermit wird bestätigt, dass","uw7e4v":"Ein Reisender","11v7ez5":"alle neun Kapitel des Bibelpfads Jordanien gegangen ist, vom Bergland Gilead im Norden bis zum Ufer des Roten Meeres, und den Titel erworben hat:","1t4ovgz":"Stempel {a} / {b} · Quiz ⭐ {c} / {b}","1h63o0r":"Begonnen {d1} · Abgeschlossen {d2}","1tiga8l":"Gewissheitsstufen","1eg3ppb":"Manche biblischen Orte sind durch die Archäologie bestätigt; andere sind „Traditionsorte“, die Gläubige seit über tausend Jahren verehren. Wir kennzeichnen das ehrlich, damit du selbst urteilen kannst.","1fcfs3x":"Zum Home-Bildschirm hinzufügen","ledqga":"Keine Installation nötig. Für ein App-Symbol:","1fydc5o":"iPhone (Safari): auf Teilen tippen → Zum Home-Bildschirm","qj9gv9":"Android (Chrome): auf ⋮ tippen → Zum Startbildschirm hinzufügen","1th4hrb":"Datenschutz","1r7a1b":"Kein Konto, keine Erhebung persönlicher Daten. Dein Standort wird nur beim Einchecken auf deinem Handy verglichen, und der Fortschritt bleibt auf deinem Handy.","rldot9":"Quellen und Nachweise","19836o4":"Bibel auf Chinesisch und Englisch: Chinese Union Version und World English Bible (beide gemeinfrei)","p0bug1":"Bibel auf Portugiesisch: ","190dhpz":"Bibel in dieser Sprache: ","mid172":"Orte und Koordinaten: ","1mwiflv":"Karte: ","1s68zx9":" Mitwirkende","1b7bgkx":"Fotos: Wikimedia Commons; Urheber und Lizenz unter jedem Foto"},"verses":{"1 Kgs 17:1":{"text":"Und Elia, der Tisbiter, von den Beisassen Gileads, sprach zu Ahab: So wahr Jehova lebt, der Gott Israels, vor dessen Angesicht ich stehe, wenn es in diesen Jahren Tau und Regen geben wird, es sei denn auf mein Wort!","ref":"1. Könige 17:1"},"1 Kgs 17:5-6":{"text":"Und er ging hin und tat nach dem Worte Jehovas: er ging hin und blieb am Bache Krith, der vor dem Jordan ist. Und die Raben brachten ihm Brot und Fleisch am Morgen, und Brot und Fleisch am Abend, und er trank aus dem Bache.","ref":"1. Könige 17:5-6"},"1 Kgs 19:19":{"text":"Und er ging von dannen und fand Elisa, den Sohn Saphats, welcher gerade pflügte mit zwölf Joch Rindern vor sich her, und er war bei dem zwölften; und Elia ging zu ihm hin und warf seinen Mantel auf ihn.","ref":"1. Könige 19:19"},"1 Kgs 19:21":{"text":"Und er kehrte von ihm zurück und nahm das Joch Rinder und schlachtete es, und mit dem Geschirr der Rinder kochte er das Fleisch derselben und gab es den Leuten, und sie aßen; und er machte sich auf und folgte Elia nach und diente ihm.","ref":"1. Könige 19:21"},"1 Kgs 19:6":{"text":"Und als er hinblickte, siehe, da lag zu seinen Häupten ein Kuchen, auf heißen Steinen gebacken, und ein Krug Wasser. Und er aß und trank und legte sich wieder hin.","ref":"1. Könige 19:6"},"1 Kgs 22:34":{"text":"Und ein Mann spannte den Bogen aufs Geratewohl und traf den König von Israel zwischen den Panzeranhang und den Panzer. Da sprach er zu seinem Wagenlenker: Wende um und führe mich aus dem Heere hinaus, denn ich bin verwundet.","ref":"1. Könige 22:34"},"1 Kgs 7:46":{"text":"Im Jordankreise ließ der König sie gießen, in dichter Erde, zwischen Sukkoth und Zarethan.","ref":"1. Könige 7:46"},"1 Kgs 9:26":{"text":"Und der König Salomo machte eine Flotte zu Ezjon-Geber, das bei Eloth, am Ufer des Schilfmeeres, im Lande Edom liegt.","ref":"1. Könige 9:26"},"1 Sam 22:3":{"text":"Und David ging von dannen nach Mizpe-Moab; und er sprach zu dem König von Moab: Laß doch meinen Vater und meine Mutter ausziehen und bei euch sein, bis ich weiß, was Gott mir tun wird.","ref":"1. Samuel 22:3"},"1 Sam 31:11-13":{"text":"Als aber die Bewohner von Jabes-Gilead über ihn hörten, was die Philister mit Saul getan hatten, da machten sich alle tapferen Männer auf und gingen die ganze Nacht; und sie nahmen den Leichnam Sauls und die Leichname seiner Söhne von der Mauer von Beth-Schan weg; und sie kamen nach Jabes zurück und verbrannten sie daselbst. Und sie nahmen ihre Gebeine und begruben sie unter der Tamariske zu Jabes, und fasteten sieben Tage.","ref":"1. Samuel 31:11-13"},"2 Cor 11:32":{"text":"In Damaskus verwahrte der Landpfleger des Königs Aretas die Stadt der Damascener, indem er mich greifen wollte,","ref":"2. Korinther 11:32"},"2 Kgs 14:7":{"text":"Er schlug die Edomiter im Salztal, zehntausend Mann, und nahm Sela ein im Streit, und er gab ihm den Namen Joktheel bis auf diesen Tag.","ref":"2. Könige 14:7"},"2 Kgs 2:11":{"text":"Und es geschah, während sie gingen und im Gehen redeten, siehe da, ein Wagen von Feuer und Rosse von Feuer, welche sie beide voneinander trennten; und Elia fuhr im Sturmwind auf gen Himmel.","ref":"2. Könige 2:11"},"2 Kgs 2:8":{"text":"Da nahm Elia seinen Mantel und wickelte ihn zusammen und schlug auf das Wasser; und es zerteilte sich dahin und dorthin, und sie gingen beide hinüber auf dem Trockenen.","ref":"2. Könige 2:8"},"2 Kgs 3:26-27":{"text":"Und als der König von Moab sah, daß ihm der Streit zu stark war, nahm er siebenhundert Mann mit sich, die das Schwert zogen, um gegen den König von Edom hin durchzubrechen; aber sie vermochten es nicht. Da nahm er seinen erstgeborenen Sohn, der an seiner Statt König werden sollte, und opferte ihn als Brandopfer auf der Mauer. Und es kam ein großer Zorn über Israel; und sie zogen von ihm ab und kehrten in ihr Land zurück.","ref":"2. Könige 3:26-27"},"2 Kgs 3:4":{"text":"Und Mesa, der König von Moab, war ein Herdenbesitzer, und er zinste dem König von Israel hunderttausend Fettschafe und hunderttausend Widder mit der Wolle.","ref":"2. Könige 3:4"},"2 Kgs 3:4-5":{"text":"Und Mesa, der König von Moab, war ein Herdenbesitzer, und er zinste dem König von Israel hunderttausend Fettschafe und hunderttausend Widder mit der Wolle. Und es geschah, als Ahab starb, da fiel der König von Moab von dem König von Israel ab.","ref":"2. Könige 3:4-5"},"2 Kgs 5:14":{"text":"Da stieg er hinab und tauchte sich im Jordan siebenmal unter, nach dem Worte des Mannes Gottes. Da wurde sein Fleisch wieder wie das Fleisch eines jungen Knaben, und er war rein.","ref":"2. Könige 5:14"},"2 Sam 11:1":{"text":"Und es geschah bei der Rückkehr des Jahres, zur Zeit, wann die Könige ausziehen, da sandte David Joab und seine Knechte mit ihm und ganz Israel; und sie richteten die Kinder Ammon zu Grunde und belagerten Rabba. David aber blieb in Jerusalem.","ref":"2. Samuel 11:1"},"2 Sam 11:15":{"text":"Und er schrieb in dem Briefe also: Stellet Urija voran, wo der Streit am stärksten ist, und ziehet euch hinter ihm zurück, daß er erschlagen werde und sterbe.","ref":"2. Samuel 11:15"},"2 Sam 12:26-27":{"text":"Und Joab stritt wider Rabba der Kinder Ammon, und er nahm die Königsstadt ein. Und Joab sandte Boten zu David und ließ ihm sagen: Ich habe wider Rabba gestritten, habe auch die Wasserstadt eingenommen;","ref":"2. Samuel 12:26-27"},"2 Sam 17:27-29":{"text":"Und es geschah, als David nach Machanaim kam, da brachten Schobi, der Sohn des Nahas, aus Rabba der Kinder Ammon, und Makir, der Sohn Ammiels, aus Lodebar, und Barsillai, der Gileaditer, aus Rogelim, Betten und Becken und Töpfergefäße, und Weizen und Gerste und Mehl, und geröstete Körner und Bohnen und Linsen und Geröstetes davon, und Honig und geronnene Milch, und Kleinvieh und Kuhkäse zu David und zu dem Volke, das bei ihm war, daß sie äßen; denn sie sprachen: Das Volk ist hungrig und matt und durstig in der Wüste.","ref":"2. Samuel 17:27-29"},"2 Sam 17:28":{"text":"Betten und Becken und Töpfergefäße, und Weizen und Gerste und Mehl, und geröstete Körner und Bohnen und Linsen und Geröstetes davon,","ref":"2. Samuel 17:28"},"2 Sam 17:29":{"text":"und Honig und geronnene Milch, und Kleinvieh und Kuhkäse zu David und zu dem Volke, das bei ihm war, daß sie äßen; denn sie sprachen: Das Volk ist hungrig und matt und durstig in der Wüste.","ref":"2. Samuel 17:29"},"2 Sam 18:33":{"text":"Da wurde der König sehr bewegt, und er stieg hinauf in das Obergemach des Tores und weinte; und während er ging, sprach er also: Mein Sohn Absalom! Mein Sohn, mein Sohn Absalom! Wäre ich doch an deiner Statt gestorben! Absalom, mein Sohn, mein Sohn!","ref":"2. Samuel 18:33"},"2 Sam 18:9":{"text":"Und Absalom stieß auf die Knechte Davids; und Absalom ritt auf einem Maultier, und das Maultier kam unter die verschlungenen Zweige einer großen Terebinthe; und er blieb mit dem Haupte an der Terebinthe hangen, und schwebte zwischen Himmel und Erde; das Maultier aber, das unter ihm war, lief davon.","ref":"2. Samuel 18:9"},"2 Sam 19:32":{"text":"Barsillai war aber sehr alt, ein Mann von achtzig Jahren; und er hatte den König versorgt, als er zu Machanaim weilte, denn er war ein sehr reicher Mann.","ref":"2. Samuel 19:32"},"2 Sam 19:37":{"text":"Laß doch deinen Knecht zurückkehren, daß ich in meiner Stadt sterbe, bei dem Grabe meines Vaters und meiner Mutter. Aber siehe, hier ist dein Knecht Kimham: Er möge mit meinem Herrn, dem König, hinübergehen; und tue ihm, was gut ist in deinen Augen.","ref":"2. Samuel 19:37"},"2 Sam 9:13":{"text":"Und Mephiboseth wohnte in Jerusalem, denn er aß beständig am Tische des Königs. Er war aber lahm an beiden Füßen.","ref":"2. Samuel 9:13"},"2 Sam 9:7":{"text":"Und David sprach zu ihm: Fürchte dich nicht; denn ich will gewißlich Güte an dir erweisen um deines Vaters Jonathan willen, und will dir alle Felder deines Vaters Saul zurückgeben; du aber sollst beständig an meinem Tische essen.","ref":"2. Samuel 9:7"},"Acts 2:11":{"text":"wie hören wir sie die großen Taten Gottes in unseren Sprachen reden?","ref":"Apostelgeschichte 2:11"},"Amos 1:14":{"text":"so werde ich ein Feuer anzünden in der Mauer von Rabba, und es wird seine Paläste verzehren unter Kriegsgeschrei am Tage des Kampfes, unter Sturm am Tage des Ungewitters;","ref":"Amos 1:14"},"Deut 1:1":{"text":"Dies sind die Worte, welche Mose zu ganz Israel geredet hat diesseit des Jordan, in der Wüste, in der Ebene, Suph gegenüber, zwischen Paran und Tophel und Laban und Hazeroth und Di-Sahab.","ref":"5. Mose 1:1"},"Deut 1:5":{"text":"Diesseit des Jordan, im Lande Moab, fing Mose an, dieses Gesetz auszulegen, indem er sprach:","ref":"5. Mose 1:5"},"Deut 2:13-14":{"text":"Nun machet euch auf und ziehet über den Bach Sered. Und wir zogen über den Bach Sered. Die Tage aber, die wir von Kades-Barnea gegangen sind, bis wir über den Bach Sered zogen, waren achtunddreißig Jahre, bis das ganze Geschlecht der Kriegsleute aus dem Lager aufgerieben war, so wie Jehova ihnen geschworen hatte.","ref":"5. Mose 2:13-14"},"Deut 2:24":{"text":"Machet euch auf, brechet auf und ziehet über den Fluß Arnon. Siehe, ich habe Sihon, den König von Hesbon, den Amoriter, und sein Land in deine Hand gegeben; beginne, nimm in Besitz und bekriege ihn!","ref":"5. Mose 2:24"},"Deut 2:36":{"text":"Von Aroer, das am Ufer des Flusses Arnon ist, und zwar von der Stadt, die im Flußtale liegt, bis Gilead war keine Stadt, die uns zu stark gewesen wäre: Alles gab Jehova, unser Gott, vor uns dahin.","ref":"5. Mose 2:36"},"Deut 2:5":{"text":"Laßt euch nicht in Streit mit ihnen ein, denn ich werde euch von ihrem Lande auch nicht den Tritt einer Fußsohle geben; denn das Gebirge Seir habe ich dem Esau als Besitztum gegeben.","ref":"5. Mose 2:5"},"Deut 2:8":{"text":"Und wir zogen weiter, an unseren Brüdern, den Kindern Esau, vorüber, die in Seir wohnen, von dem Wege der Ebene, von Elath und von Ezjon-Geber her; und wir wandten uns und zogen des Weges nach der Wüste von Moab.","ref":"5. Mose 2:8"},"Deut 2:9":{"text":"Und Jehova sprach zu mir: Befeinde Moab nicht und laß dich nicht in Streit mit ihnen ein, denn ich werde dir von seinem Lande kein Besitztum geben; denn Ar habe ich den Kindern Lot als Besitztum gegeben. -","ref":"5. Mose 2:9"},"Deut 34:1":{"text":"Und Mose stieg von den Ebenen Moabs auf den Berg Nebo, den Gipfel des Pisga, der Jericho gegenüber ist. Und Jehova ließ ihn das ganze Land sehen:","ref":"5. Mose 34:1"},"Deut 34:3":{"text":"und den Süden und den Jordankreis, die Niederung von Jericho, der Palmenstadt, bis Zoar.","ref":"5. Mose 34:3"},"Deut 34:4":{"text":"Und Jehova sprach zu ihm: Das ist das Land, welches ich Abraham, Isaak und Jakob zugeschworen habe, indem ich sprach: Deinem Samen will ich es geben. Ich habe es dich mit deinen Augen sehen lassen, aber du sollst nicht hinübergehen.","ref":"5. Mose 34:4"},"Deut 34:5-6":{"text":"Und Mose, der Knecht Jehovas, starb daselbst im Lande Moab, nach dem Worte Jehovas. Und er begrub ihn im Tale, im Lande Moab, Beth-Peor gegenüber; und niemand weiß sein Grab bis auf diesen Tag.","ref":"5. Mose 34:5-6"},"Deut 3:11":{"text":"Denn nur Og, der König von Basan, war von dem Überrest der Riesen übriggeblieben. Siehe, sein Bett, ein Bett von Eisen, ist es nicht in Rabba der Kinder Ammon? Seine Länge mißt neun Ellen und seine Breite vier Ellen, nach dem Ellenbogen eines Mannes.","ref":"5. Mose 3:11"},"Deut 4:43":{"text":"Bezer in der Wüste, im Lande der Ebene, für die Rubeniter, und Ramoth in Gilead für die Gaditer, und Golan in Basan für die Manassiter.","ref":"5. Mose 4:43"},"Deut 8:8":{"text":"ein Land von Weizen und Gerste und Weinstöcken und Feigenbäumen und Granatbäumen;","ref":"5. Mose 8:8"},"Exod 12:22":{"text":"und nehmet einen Büschel Ysop und tauchet ihn in das Blut, das in dem Becken ist, und streichet von dem Blute, das in dem Becken ist, an die Oberschwelle und an die beiden Pfosten; ihr aber, keiner von euch soll zur Türe seines Hauses hinausgehen bis an den Morgen.","ref":"2. Mose 12:22"},"Ezek 47:10":{"text":"Und es wird geschehen, daß Fischer an demselben stehen werden: von En-Gedi bis En-Eglaim werden Plätze sein zur Ausbreitung der Netze. Nach ihrer Art werden seine Fische sein, sehr zahlreich, wie die Fische des großen Meeres.","ref":"Hesekiel 47:10"},"Ezek 47:8":{"text":"Und er sprach zu mir: Diese Wasser fließen hinaus nach dem östlichen Kreise, und fließen in die Ebene hinab und gelangen in das Meer; und werden sie in das Meer hinausgeführt, so werden die Wasser des Meeres gesund werden.","ref":"Hesekiel 47:8"},"Ezek 47:9":{"text":"Und es wird geschehen, daß alle lebendigen Seelen, die da wimmeln, überall wohin der Doppelfluß kommt, leben werden. Und der Fische werden sehr viele sein; denn wenn diese Wasser dorthin kommen, so werden die Wasser des Meeres gesund werden, und alles wird leben, wohin der Fluß kommt.","ref":"Hesekiel 47:9"},"Gal 1:17":{"text":"und ging auch nicht hinauf nach Jerusalem zu denen, die vor mir Apostel waren, sondern ich ging fort nach Arabien und kehrte wiederum nach Damaskus zurück.","ref":"Galater 1:17"},"Gen 19:22-23":{"text":"Eile, rette dich dorthin; denn ich kann nichts tun, bis du dorthin gekommen bist. Daher hat man der Stadt den Namen Zoar gegeben. Die Sonne ging auf über der Erde, als Lot in Zoar ankam.","ref":"1. Mose 19:22-23"},"Gen 19:26":{"text":"Und sein Weib sah sich hinter ihm um und ward zu einer Salzsäule.","ref":"1. Mose 19:26"},"Gen 19:30":{"text":"Und Lot zog hinauf von Zoar und wohnte im Gebirge, und seine beiden Töchter mit ihm; denn er fürchtete sich, in Zoar zu wohnen. Und er wohnte in einer Höhle, er und seine beiden Töchter.","ref":"1. Mose 19:30"},"Gen 19:37-38":{"text":"Und die Erstgeborene gebar einen Sohn, und sie gab ihm den Namen Moab; dieser ist der Vater der Moabiter bis auf diesen Tag. Und die Jüngere, auch sie gebar einen Sohn, und sie gab ihm den Namen Ben Ammi; dieser ist der Vater der Kinder Ammon bis auf diesen Tag.","ref":"1. Mose 19:37-38"},"Gen 19:38":{"text":"Und die Jüngere, auch sie gebar einen Sohn, und sie gab ihm den Namen Ben Ammi; dieser ist der Vater der Kinder Ammon bis auf diesen Tag.","ref":"1. Mose 19:38"},"Gen 25:34":{"text":"Und Jakob gab Esau Brot und ein Gericht Linsen; und er aß und trank und stand auf und ging davon. So verachtete Esau das Erstgeburtsrecht.","ref":"1. Mose 25:34"},"Gen 31:49":{"text":"und Mizpa, weil er sprach: Jehova sei Wächter zwischen mir und dir, wenn wir einer vor dem anderen verborgen sein werden!","ref":"1. Mose 31:49"},"Gen 32:1-2":{"text":"Und Jakob zog seines Weges, und es begegneten ihm Engel Gottes. Und Jakob sprach, als er sie sah: Dies ist das Heerlager Gottes. Und er gab jenem Orte den Namen Machanaim.","ref":"1. Mose 32:1-2"},"Gen 32:24":{"text":"Und Jakob blieb allein übrig; und es rang ein Mann mit ihm, bis die Morgenröte aufging.","ref":"1. Mose 32:24"},"Gen 32:28":{"text":"Da sprach er: Nicht Jakob soll hinfort dein Name heißen, sondern Israel; denn du hast mit Gott und mit Menschen gerungen und hast obsiegt.","ref":"1. Mose 32:28"},"Gen 32:30-31":{"text":"Und Jakob gab dem Orte den Namen Pniel: denn ich habe Gott von Angesicht zu Angesicht gesehen, und meine Seele ist gerettet worden! Und die Sonne ging ihm auf, als er über Pniel hinaus war; und er hinkte an seiner Hüfte.","ref":"1. Mose 32:30-31"},"Gen 33:16":{"text":"Und Esau kehrte an selbigem Tage seines Weges zurück nach Seir.","ref":"1. Mose 33:16"},"Gen 33:17":{"text":"Und Jakob brach auf nach Sukkoth und baute sich ein Haus, und seinem Vieh machte er Hütten; darum gab er dem Orte den Namen Sukkoth.","ref":"1. Mose 33:17"},"Gen 33:4":{"text":"Und Esau lief ihm entgegen und umarmte ihn und fiel ihm um den Hals und küßte ihn; und sie weinten.","ref":"1. Mose 33:4"},"Gen 36:8":{"text":"Und Esau wohnte auf dem Gebirge Seir. Esau, das ist Edom.","ref":"1. Mose 36:8"},"Heb 12:1":{"text":"Deshalb nun, da wir eine so große Wolke von Zeugen um uns haben, laßt auch uns, indem wir jede Bürde und die leicht umstrickende Sünde ablegen, mit Ausharren laufen den vor uns liegenden Wettlauf,","ref":"Hebräer 12:1"},"Hos 10:14":{"text":"Und es wird sich ein Getümmel erheben unter deinen Völkern, und alle deine Festen werden zerstört werden, wie Schalman Beth-Arbel zerstörte am Tage des Krieges; die Mutter samt den Kindern wurde zerschmettert.","ref":"Hosea 10:14"},"Isa 15:4":{"text":"Und Hesbon schreit und Elale; bis Jahaz wird ihre Stimme gehört. Darum schreien die Gerüsteten Moabs laut auf, seine Seele bebt in ihm.","ref":"Jesaja 15:4"},"Isa 16:10":{"text":"und verschwunden sind Freude und Frohlocken aus dem Fruchtgefilde, und in den Weinbergen wird nicht gejubelt, nicht gejauchzt; der Keltertreter tritt keinen Wein in den Keltern; dem lauten Rufe habe ich ein Ende gemacht.","ref":"Jesaja 16:10"},"Isa 63:1":{"text":"Wer ist dieser, der von Edom kommt, von Bozra in hochroten Kleidern, dieser, prächtig in seinem Gewande, der einherzieht in der Größe seiner Kraft? Ich bin's, der in Gerechtigkeit redet, der mächtig ist zu retten. -","ref":"Jesaja 63:1"},"Jas 5:17":{"text":"Elias war ein Mensch von gleichen Gemütsbewegungen wie wir; und er betete ernstlich, daß es nicht regnen möge, und es regnete nicht auf der Erde drei Jahre und sechs Monate.","ref":"Jakobus 5:17"},"Jer 48:21":{"text":"Und das Gericht ist gekommen über das Land der Ebene, über Cholon und über Jahza und über Mephaath,","ref":"Jeremia 48:21"},"Jer 49:7":{"text":"Über Edom. So spricht Jehova der Heerscharen: Ist keine Weisheit mehr in Teman? Ist den Verständigen der Rat entschwunden, ist ihre Weisheit ausgeschüttet?","ref":"Jeremia 49:7"},"Jer 8:22":{"text":"Ist kein Balsam in Gilead, oder kein Arzt daselbst? Denn warum ist der Tochter meines Volkes kein Verband angelegt worden?","ref":"Jeremia 8:22"},"Job 1:1":{"text":"Es war Mann im Lande Uz, sein Name war Hiob; und selbiger Mann war vollkommen und rechtschaffen und gottesfürchtig und das Böse meidend.","ref":"Hiob 1:1"},"Job 1:21":{"text":"Und er sprach: Nackt bin ich aus meiner Mutter Leibe gekommen, und nackt werde ich dahin zurückkehren; Jehova hat gegeben, und Jehova hat genommen, der Name Jehovas sei gepriesen!","ref":"Hiob 1:21"},"Job 2:11":{"text":"Und die drei Freunde Hiobs hörten all dieses Unglück, das über ihn gekommen war; und sie kamen, ein jeder aus seinem Orte: Eliphas, der Temaniter, und Bildad, der Schuchiter, und Zophar, der Naamathiter; und sie verabredeten sich miteinander zu kommen, um ihm ihr Beileid zu bezeugen und ihn zu trösten.","ref":"Hiob 2:11"},"John 10:40":{"text":"Und er ging wieder weg jenseit des Jordan an den Ort, wo Johannes zuerst taufte, und er blieb daselbst.","ref":"Johannes 10:40"},"John 1:28":{"text":"Dies geschah zu Bethanien, jenseit des Jordan, wo Johannes taufte.","ref":"Johannes 1:28"},"John 3:14":{"text":"Und gleichwie Moses in der Wüste die Schlange erhöhte, also muß der Sohn des Menschen erhöht werden,","ref":"Johannes 3:14"},"Josh 13:18":{"text":"und Jahza und Kedemoth und Mephaath,","ref":"Josua 13:18"},"Josh 13:19":{"text":"und Kirjathaim und Sibma und Zereth-Schachar auf dem Berge der Talebene,","ref":"Josua 13:19"},"Josh 20:3":{"text":"daß dahin fliehe ein Totschläger, der jemand aus Versehen, unabsichtlich, erschlagen hat; und sie seien euch zur Zuflucht vor dem Bluträcher.","ref":"Josua 20:3"},"Josh 2:1":{"text":"Und Josua, der Sohn Nuns, sandte von Sittim heimlich zwei Männer als Kundschafter aus und sprach: Gehet, besehet das Land und Jericho. Und sie gingen hin und kamen in das Haus einer Hure, namens Rahab; und sie legten sich daselbst nieder.","ref":"Josua 2:1"},"Josh 3:16":{"text":"da blieben die von oben herabfließenden Wasser stehen; sie richteten sich auf wie ein Damm, sehr fern, bei Adam, der Stadt, die seitwärts von Zarethan liegt; und die nach dem Meere der Ebene, dem Salzmeere, hinabfließenden wurden völlig abgeschnitten. Und das Volk zog hindurch, Jericho gegenüber.","ref":"Josua 3:16"},"Judg 11:32-33":{"text":"Und so zog Jephtha gegen die Kinder Ammon, um wider sie zu streiten; und Jehova gab sie in seine Hand. Und er schlug sie von Aroer an, bis man nach Minnith kommt, zwanzig Städte, und bis nach Abel-Keramim, und er richtete eine sehr große Niederlage unter ihnen an; und die Kinder Ammon wurden gebeugt vor den Kindern Israel.","ref":"Richter 11:32-33"},"Judg 12:6":{"text":"Und sagte er: Nein! so sprachen sie zu ihm: Sage doch: Schibboleth! Und sagte er: Sibboleth, und brachte es nicht fertig, richtig zu sprechen, dann ergriffen sie ihn und schlachteten ihn an den Furten des Jordan. Und es fielen in jener Zeit von Ephraim zweiundvierzigtausend.","ref":"Richter 12:6"},"Judg 8:11":{"text":"Und Gideon zog hinauf des Weges zu den Zeltbewohnern, östlich von Nobach und Jogbeha; und er schlug das Lager, und das Lager war sorglos.","ref":"Richter 8:11"},"Judg 8:17":{"text":"Und den Turm zu Pnuel riß er nieder und erschlug die Männer der Stadt.","ref":"Richter 8:17"},"Luke 17:32":{"text":"Gedenket an Lots Weib!","ref":"Lukas 17:32"},"Luke 21:20-21":{"text":"Wenn ihr aber Jerusalem von Heerscharen umzingelt sehet, alsdann erkennet, daß ihre Verwüstung nahe gekommen ist. Daß alsdann, die in Judäa sind, auf die Berge fliehen, und die in ihrer Mitte sind, daraus entweichen, und die auf dem Lande sind, nicht in sie hineingehen.","ref":"Lukas 21:20-21"},"Luke 4:27":{"text":"Und viele Aussätzige waren zur Zeit des Propheten Elisa in Israel, und keiner von ihnen wurde gereinigt, als nur Naaman, der Syrer.","ref":"Lukas 4:27"},"Mark 1:6":{"text":"Johannes aber war bekleidet mit Kamelhaaren und einem ledernen Gürtel um seine Lenden; und er aß Heuschrecken und wilden Honig.","ref":"Markus 1:6"},"Mark 5:1":{"text":"Und sie kamen an das jenseitige Ufer des Sees in das Land der Gadarener.","ref":"Markus 5:1"},"Mark 5:19-20":{"text":"Und er ließ es ihm nicht zu, sondern spricht zu ihm: Gehe hin nach deinem Hause zu den Deinigen und verkünde ihnen, wieviel der Herr an dir getan, und wie er sich deiner erbarmt hat. Und er ging hin und fing an, in der Dekapolis auszurufen, wieviel Jesus an ihm getan hatte; und alle verwunderten sich.","ref":"Markus 5:19-20"},"Mark 5:20":{"text":"Und er ging hin und fing an, in der Dekapolis auszurufen, wieviel Jesus an ihm getan hatte; und alle verwunderten sich.","ref":"Markus 5:20"},"Mark 6:17-18":{"text":"Denn er, Herodes, hatte hingesandt und den Johannes greifen und ihn im Gefängnis binden lassen, um der Herodias willen, des Weibes seines Bruders Philippus, weil er sie geheiratet hatte. Denn Johannes hatte dem Herodes gesagt: Es ist dir nicht erlaubt, das Weib deines Bruders zu haben.","ref":"Markus 6:17-18"},"Mark 6:27-28":{"text":"Und alsbald schickte der König einen von der Leibwache und befahl, sein Haupt zu bringen. Der aber ging hin und enthauptete ihn im Gefängnis; und er brachte sein Haupt auf einer Schüssel und gab es dem Mägdlein, und das Mägdlein gab es ihrer Mutter.","ref":"Markus 6:27-28"},"Mark 6:31":{"text":"Und er sprach zu ihnen: Kommet ihr selbst her an einen öden Ort besonders und ruhet ein wenig aus. Denn derer, die da kamen und gingen, waren viele, und sie fanden nicht einmal Zeit, um zu essen.","ref":"Markus 6:31"},"Mark 7:31":{"text":"Und als er aus dem Gebiet von Tyrus und Sidon wieder weggegangen war, kam er an den See von Galiläa, mitten durch das Gebiet von Dekapolis.","ref":"Markus 7:31"},"Matt 3:16-17":{"text":"Und als Jesus getauft war, stieg er alsbald von dem Wasser herauf; und siehe, die Himmel wurden ihm aufgetan, und er sah den Geist Gottes wie eine Taube herniederfahren und auf ihn kommen. Und siehe, eine Stimme kommt aus den Himmeln, welche spricht: Dieser ist mein geliebter Sohn, an welchem ich Wohlgefallen gefunden habe.","ref":"Matthäus 3:16-17"},"Matt 4:25":{"text":"Und es folgten ihm große Volksmengen von Galiläa und Dekapolis und Jerusalem und Judäa und von jenseit des Jordan.","ref":"Matthäus 4:25"},"Matt 8:28":{"text":"Und als er an das jenseitige Ufer gekommen war, in das Land der Gergesener, begegneten ihm zwei Besessene, die aus den Grüften hervorkamen, sehr wütend, so daß niemand jenes Weges vorbeizugehen vermochte.","ref":"Matthäus 8:28"},"Matt 8:32":{"text":"Und er sprach zu ihnen: Gehet hin. Sie aber fuhren aus und fuhren in die Herde Schweine. Und siehe, die ganze Herde Schweine stürzte sich den Abhang hinab in den See, und sie kamen um in dem Gewässer.","ref":"Matthäus 8:32"},"Num 20:11":{"text":"Und Mose erhob seine Hand und schlug den Felsen mit seinem Stabe zweimal; da kam viel Wasser heraus, und die Gemeinde trank und ihr Vieh.","ref":"4. Mose 20:11"},"Num 20:17":{"text":"Laß uns doch durch dein Land ziehen! Wir wollen nicht durch die Äcker und durch die Weinberge ziehen und wollen kein Wasser aus den Brunnen trinken; auf der Straße des Königs wollen wir ziehen und nicht ausbiegen zur Rechten noch zur Linken, bis wir durch dein Gebiet gezogen sind.","ref":"4. Mose 20:17"},"Num 20:27-28":{"text":"Und Mose tat, so wie Jehova geboten hatte, und sie stiegen auf den Berg Hor, vor den Augen der ganzen Gemeinde. Und Mose zog Aaron seine Kleider aus und legte sie seinem Sohne Eleasar an; und Aaron starb daselbst auf dem Gipfel des Berges; und Mose und Eleasar stiegen von dem Berge herab.","ref":"4. Mose 20:27-28"},"Num 21:13":{"text":"Von dort brachen sie auf und lagerten sich jenseit des Arnon, der in der Wüste ist, der aus dem Gebiete der Amoriter hervorgeht. Denn der Arnon ist die Grenze von Moab, zwischen Moab und den Amoritern.","ref":"4. Mose 21:13"},"Num 21:16":{"text":"Und von dort zogen sie nach Beer; das ist der Brunnen, von welchem Jehova zu Mose sprach: Versammle das Volk, und ich will ihnen Wasser geben.","ref":"4. Mose 21:16"},"Num 21:22":{"text":"Laß mich durch dein Land ziehen! Wir wollen nicht in die Äcker und in die Weinberge ausbiegen, wir wollen kein Wasser aus den Brunnen trinken; auf der Straße des Königs wollen wir ziehen, bis wir durch dein Gebiet gezogen sind.","ref":"4. Mose 21:22"},"Num 21:23-24":{"text":"Aber Sihon gestattete Israel nicht, durch sein Gebiet zu ziehen; und Sihon versammelte all sein Volk und zog aus, Israel entgegen in die Wüste, und kam nach Jahaz und stritt wider Israel. Und Israel schlug ihn mit der Schärfe des Schwertes und nahm sein Land in Besitz, vom Arnon bis an den Jabbok, bis zu den Kindern Ammon; denn die Grenze der Kinder Ammon war fest.","ref":"4. Mose 21:23-24"},"Num 21:26":{"text":"Denn Hesbon war die Stadt Sihons, des Königs der Amoriter; und dieser hatte wider den früheren König von Moab gestritten und hatte sein ganzes Land bis an den Arnon aus seiner Hand genommen.","ref":"4. Mose 21:26"},"Num 21:30":{"text":"Da haben wir auf sie geschossen; Hesbon ist verloren bis Dibon; da haben wir verwüstet bis Nophach, Feuer bis Medeba!","ref":"4. Mose 21:30"},"Num 21:9":{"text":"Und Mose machte eine Schlange von Erz und tat sie auf die Stange; und es geschah, wenn eine Schlange jemand gebissen hatte, und er schaute auf zu der ehernen Schlange, so blieb er am Leben.","ref":"4. Mose 21:9"},"Num 22:1":{"text":"Und die Kinder Israel brachen auf und lagerten sich in den Ebenen Moabs, jenseit des Jordan von Jericho.","ref":"4. Mose 22:1"},"Num 22:5":{"text":"Und er sandte Boten zu Bileam, dem Sohne Beors, nach Pethor, das am Strome ist, in das Land der Kinder seines Volkes, um ihn zu rufen, und er ließ ihm sagen: Siehe, ein Volk ist aus Ägypten gezogen; siehe, es bedeckt die Fläche des Landes, und es liegt mir gegenüber.","ref":"4. Mose 22:5"},"Num 23:14":{"text":"Und er nahm ihn mit nach dem Felde der Wächter, auf den Gipfel des Pisga; und er baute sieben Altäre und opferte einen Farren und einen Widder auf jedem Altar.","ref":"4. Mose 23:14"},"Num 24:17":{"text":"Ich sehe ihn, aber nicht jetzt, ich schaue ihn, aber nicht nahe; es tritt hervor ein Stern aus Jakob, und ein Zepter erhebt sich aus Israel und zerschlägt die Seiten Moabs und zerschmettert alle Söhne des Getümmels.","ref":"4. Mose 24:17"},"Num 25:1":{"text":"Und Israel blieb in Sittim. Und das Volk fing an zu huren mit den Töchtern Moabs;","ref":"4. Mose 25:1"},"Num 32:1":{"text":"Und die Kinder Ruben und die Kinder Gad hatten viel Vieh, in gewaltiger Menge; und sie sahen das Land Jaser und das Land Gilead, und siehe, der Ort war ein Ort für Vieh.","ref":"4. Mose 32:1"},"Num 32:34":{"text":"Und die Kinder Gad bauten Dibon und Ataroth und Aroer,","ref":"4. Mose 32:34"},"Num 32:35":{"text":"und Ateroth-Schofan und Jaser und Jogbeha,","ref":"4. Mose 32:35"},"Num 32:37-38":{"text":"Und die Kinder Ruben bauten Hesbon und Elale und Kirjathaim, und Nebo und Baal-Meon, deren Namen geändert wurden, und Sibma; und sie benannten die Städte, die sie bauten, mit anderen Namen. -","ref":"4. Mose 32:37-38"},"Num 32:6":{"text":"Und Mose sprach zu den Kindern Gad und zu den Kindern Ruben: Sollen eure Brüder in den Streit ziehen, und ihr wollt hier bleiben?","ref":"4. Mose 32:6"},"Num 33:42":{"text":"Und sie brachen auf von Zalmona und lagerten sich in Punon.","ref":"4. Mose 33:42"},"Num 33:49":{"text":"Und sie lagerten sich am Jordan, von Beth-Jesimoth bis Abel-Sittim in den Ebenen Moabs.","ref":"4. Mose 33:49"},"Ruth 1:1":{"text":"Und es geschah in den Tagen, als die Richter richteten, da entstand eine Hungersnot im Lande. Und ein Mann von Bethlehem-Juda zog hin, um sich in den Gefilden Moabs aufzuhalten, er und sein Weib und seine beiden Söhne.","ref":"Ruth 1:1"},"Ruth 1:16":{"text":"Aber Ruth sprach: Dringe nicht in mich, dich zu verlassen, hinter dir weg umzukehren; denn wohin du gehst, will ich gehen, und wo du weilst, will ich weilen; dein Volk ist mein Volk, und dein Gott ist mein Gott;","ref":"Ruth 1:16"},"Song 7:4":{"text":"Dein Hals ist wie ein Turm von Elfenbein; deine Augen wie die Teiche zu Hesbon am Tore der volkreichen Stadt; deine Nase wie der Libanonturm, der nach Damaskus hinschaut.","ref":"Hohelied 7:4"},"1 Kgs 22:48":{"text":"Josaphat baute Tarsisschiffe, um nach Ophir zu fahren und Gold zu holen; aber man fuhr nicht, denn die Schiffe wurden bei Ezjon-Geber zertrümmert.","ref":"1. Könige 22:48"},"Num 21:17":{"text":"Damals sang Israel dieses Lied: Herauf, Brunnen! Singet ihm zu! Brunnen, den Fürsten gegraben, den die Edlen des Volkes, mit dem Gesetzgeber, gehöhlt haben mit ihren Stäben!","ref":"4. Mose 21:17"}}};
